# 1. bech32.go - bech32 encoding/decoding for age keys
# 2. scrypt.go - scrypt KDF
# 3. age.go - the age format
# 4. main.go - CLI interface

# Let me start with the bech32 implementation
cat > /tmp/agecli/bech32.go << 'GOEOF'
package main

import (
	"fmt"
	"strings"
)

// bech32 encoding/decoding for age keys
// Reference: BIP-0173 (Bech32)

const bech32Charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

var bech32CharsetReverse [256]int8

func init() {
	for i := range bech32CharsetReverse {
		bech32CharsetReverse[i] = -1
	}
	for i, c := range bech32Charset {
		bech32CharsetReverse[c] = int8(i)
	}
}

func bech32PolymodStep(pre uint32) uint32 {
	b := pre >> 25
	return ((pre & 0x1FFFFFF) << 5) ^
		(-((b >> 0) & 1) & 0x3b6a57b2) ^
		(-((b >> 1) & 1) & 0x26508e6d) ^
		(-((b >> 2) & 1) & 0x1ea119fa) ^
		(-((b >> 3) & 1) & 0x3d4233dd) ^
		(-((b >> 4) & 1) & 0x2a1462b3)
}

func bech32CreateChecksum(hrp string, data []byte) []byte {
	values := bech32HrpExpand(hrp)
	values = append(values, data...)
	values = append(values, []byte{0, 0, 0, 0, 0, 0}...)
	polymod := bech32Polymod(values) ^ 1
	result := make([]byte, 6)
	for i := range result {
		result[i] = byte((polymod >> (5 * (5 - i))) & 31)
	}
	return result
}

func bech32VerifyChecksum(hrp string, data []byte) bool {
	values := bech32HrpExpand(hrp)
	values = append(values, data...)
	return bech32Polymod(values) == 1
}

func bech32HrpExpand(hrp string) []byte {
	result := make([]byte, len(hrp)*2+1)
	for i := 0; i < len(hrp); i++ {
		result[i] = hrp[i] >> 5
	}
	result[len(hrp)] = 0
	for i := 0; i < len(hrp); i++ {
		result[len(hrp)+1+i] = hrp[i] & 31
	}
	return result
}

func bech32Polymod(values []byte) uint32 {
	chk := uint32(1)
	for _, v := range values {
		chk = bech32PolymodStep(chk) ^ uint32(v)
	}
	return chk
}

// bech32Encode encodes data (bytes) as bech32 with given hrp
func bech32Encode(hrp string, data []byte) string {
	// Convert 8-bit data to 5-bit data
	converted := convertBits(data, 8, 5, true)
	checksum := bech32CreateChecksum(hrp, converted)
	combined := append(converted, checksum...)
	var sb strings.Builder
	sb.WriteString(hrp)
	sb.WriteByte('1')
	for _, c := range combined {
		sb.WriteByte(bech32Charset[c])
	}
	return sb.String()
}

// bech32Decode decodes a bech32 string, returning hrp and data (bytes)
func bech32Decode(s string) (string, []byte, error) {
	// Find the last '1'
	if len(s) < 8 {
		return "", nil, fmt.Errorf("bech32: string too short")
	}
	pos := strings.LastIndexByte(s, '1')
	if pos < 1 || pos+7 > len(s) {
		return "", nil, fmt.Errorf("bech32: invalid separator position")
	}
	hrp := strings.ToLower(s[:pos])
	data := make([]byte, len(s)-pos-1)
	for i, c := range s[pos+1:] {
		d := bech32CharsetReverse[c]
		if d == -1 {
			// Try lowercase
			lc := strings.ToLower(string(c))[0]
			d = bech32CharsetReverse[lc]
			if d == -1 {
				return "", nil, fmt.Errorf("bech32: invalid character at position %d: %c", pos+1+i, c)
			}
		}
		data[i] = byte(d)
	}
	if !bech32VerifyChecksum(hrp, data) {
		return "", nil, fmt.Errorf("bech32: invalid checksum")
	}
	// Remove checksum (last 6 bytes)
	data = data[:len(data)-6]
	// Convert 5-bit to 8-bit
	decoded, err := convertBitsNopad(data, 5, 8, false)
	if err != nil {
		return "", nil, err
	}
	return hrp, decoded, nil
}

func convertBits(data []byte, fromBits, toBits uint, pad bool) []byte {
	acc := 0
	bits := uint(0)
	var result []byte
	maxv := (1 << toBits) - 1
	for _, value := range data {
		acc = (acc << fromBits) | int(value)
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			result = append(result, byte((acc>>bits)&maxv))
		}
	}
	if pad {
		if bits > 0 {
			result = append(result, byte((acc<<(toBits-bits))&maxv))
		}
	}
	return result
}

func convertBitsNopad(data []byte, fromBits, toBits uint, pad bool) ([]byte, error) {
	acc := 0
	bits := uint(0)
	var result []byte
	maxv := (1 << toBits) - 1
	maxacc := (1 << (fromBits + toBits - 1)) - 1
	for _, value := range data {
		acc = ((acc << fromBits) | int(value)) & maxacc
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			result = append(result, byte((acc>>bits)&maxv))
		}
	}
	if bits >= fromBits || ((acc<<(toBits-bits))&maxv) != 0 {
		return nil, fmt.Errorf("bech32: invalid padding in data")
	}
	return result, nil
}
GOEOF

