	b := pre >> 25
	return ((pre & 0x1FFFFFF) << 5) ^
		(-(uint32((b>>0)&1)) & 0x3b6a57b2) ^
		(-(uint32((b>>1)&1)) & 0x26508e6d) ^
		(-(uint32((b>>2)&1)) & 0x1ea119fa) ^
		(-(uint32((b>>3)&1)) & 0x3d4233dd) ^
		(-(uint32((b>>4)&1)) & 0x2a1462b3)
