	values := bech32HrpExpand(hrp)
	values = append(values, data...)
	values = append(values, []byte{0, 0, 0, 0, 0, 0}...)
	polymod := bech32Polymod(values) ^ 1
	result := make([]byte, 6)
	for i := range result {
		result[i] = byte((polymod >> (5 * (5 - uint(i)))) & 31)
	}
	return result
