		}
		data5bit[i] = byte(d)
	}
	if !bech32VerifyChecksum(hrp, data5bit) {
		return "", nil, fmt.Errorf("bech32: invalid checksum")
	}
	// Remove checksum
	data5bit = data5bit[:len(data5bit)-6]
	decoded, err := convertBits5to8(data5bit)
	if err != nil {
		return "", nil, err
	}
	return hrp, decoded, nil
}

