	acc := 0
	bits := uint(0)
	var result []byte
	for _, b := range data {
		acc = (acc << 8) | int(b)
		bits += 8
		for bits >= 5 {
			bits -= 5
			result = append(result, byte((acc>>bits)&31))
		}
	}
	if bits > 0 {
		result = append(result, byte((acc<<(5-bits))&31))
	}
	return result
}

func convertBits5to8(data []byte) ([]byte, error) {
	acc := 0
	bits := uint(0)
	var result []byte
	for _, b := range data {
		acc = (acc << 5) | int(b)
		bits += 5
		for bits >= 8 {
			bits -= 8
			result = append(result, byte((acc>>bits)&255))
		}
	}
	if bits >= 5 || ((acc<<(8-bits))&255) != 0 {
		return nil, fmt.Errorf("bech32: invalid padding in data")
	}
	return result, nil
}
