package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
)

// scrypt implements the scrypt password-based key derivation function
// (RFC 7914)
func scryptKey(password, salt []byte, N, r, p, keyLen int) ([]byte, error) {
	if N <= 1 || (N&(N-1)) != 0 {
		return nil, fmt.Errorf("scrypt: N must be > 1 and a power of 2")
	}
	if uint64(r)*uint64(p) >= (1 << 30) {
		return nil, fmt.Errorf("scrypt: r*p too large")
	}
	if N > (1<<32)/uint64(r) {
		// overflow check
	}
	// B = PBKDF2-HMAC-SHA256(password, salt, 1, p*128*r)
	B := pbkdf2Key(password, salt, 1, p*128*r)

	xy := make([]uint32, 64*r)
	v := make([]uint32, 32*N*r)

	for i := 0; i < p; i++ {
		scryptSMix(B[i*128*r:(i+1)*128*r], r, N, v, xy)
	}

