	denInv := new(big.Int).ModInverse(den, p)
	if denInv == nil {
		return nil, fmt.Errorf("ed25519: denominator has no inverse (degenerate point)")
	}

	u := new(big.Int).Mul(num, denInv)
	u.Mod(u, p)

	// Convert to little-endian bytes
	uBytes := u.Bytes()
	result := make([]byte, 32)
	// uBytes is big-endian, we need little-endian
	for i, b := range uBytes {
		result[len(uBytes)-1-i] = b
	}
	return result, nil
}

// reverseBytes reverses a byte slice
func reverseBytes(b []byte) []byte {
	result := make([]byte, len(b))
	for i, v := range b {
		result[len(b)-1-i] = v
	}
	return result
}

// ed25519PrivKeyToX25519 converts an Ed25519 private key (seed) to X25519
// The X25519 private key is SHA-512(seed)[0:32] with clamping
func ed25519PrivKeyToX25519(seed []byte) []byte {
	h := sha512.Sum512(seed)
	key := h[:32]
	key[0] &= 248
	key[31] &= 127
	key[31] |= 64
	return key
}
