	// [0..10] = 11-byte big-endian counter
	// [11] = is_last_chunk (0 or 1)

	// For counter = 0, is_last = false:
	// 00 00 00 00 00 00 00 00 00 00 00 00
	// For counter = 0, is_last = true:
	// 00 00 00 00 00 00 00 00 00 00 00 01
	// For counter = 1, is_last = false:
	// 00 00 00 00 00 00 00 00 00 00 01 00

	// The 11 byte counter gives us bytes [0:11]
	// counter bytes go into positions 0-10
	for i := 0; i < 11; i++ {
		nonce[10-i] = byte(counter >> (uint(i) * 8))
	}
