// ageDecrypt decrypts an age file
func ageDecrypt(dst io.Writer, src io.Reader, identities []identity) error {
	r := bufio.NewReader(src)

	// Parse header
	stanzas, fileKey, err := parseAndDecryptHeader(r, identities)
	if err != nil {
		return err
	}
	_ = stanzas

	// Decrypt payload
	return streamDecrypt(dst, r, fileKey)
}

func parseAndDecryptHeader(r *bufio.Reader, identities []identity) ([]*Stanza, []byte, error) {
	// Read version line
	versionLine, err := r.ReadString('\n')
	if err != nil {
		return nil, nil, fmt.Errorf("parsing age header: failed to read version line: %w", err)
	}
	versionLine = strings.TrimSuffix(versionLine, "\n")
	if versionLine != ageHeader {
		return nil, nil, fmt.Errorf("parsing age header: unexpected intro: %q", versionLine+"\n")
	}

	// Read stanzas
	var stanzas []*Stanza
	var headerBytes bytes.Buffer
	fmt.Fprintf(&headerBytes, "%s\n", ageHeader)

	for {
		line, err := r.ReadString('\n')
		if err != nil {
			return nil, nil, fmt.Errorf("parsing age header: unexpected EOF")
		}

		if strings.HasPrefix(line, "--- ") {
			// End of header - compute and verify MAC later
			macStr := strings.TrimSpace(line[4:])
			mac, err := b64.DecodeString(macStr)
			if err != nil {
				return nil, nil, fmt.Errorf("parsing age header: invalid MAC encoding")
			}
			if len(mac) != 32 {
				return nil, nil, fmt.Errorf("parsing age header: invalid MAC length")
			}

			// Try each identity to decrypt the file key
			fileKey, err := tryDecryptFileKey(stanzas, identities)
			if err != nil {
				return nil, nil, err
			}

			// Verify MAC
			macKey := make([]byte, 32)
			hkdfReader := hkdf.New(sha256.New, fileKey, nil, []byte("header"))
			if _, err := io.ReadFull(hkdfReader, macKey); err != nil {
				return nil, nil, err
			}
			expected := hmac.New(sha256.New, macKey)
			expected.Write(headerBytes.Bytes())
			if !hmac.Equal(expected.Sum(nil), mac) {
				return nil, nil, fmt.Errorf("header MAC mismatch")
			}

			return stanzas, fileKey, nil
		}

		headerBytes.WriteString(line)

		if !strings.HasPrefix(line, "-> ") {
			return nil, nil, fmt.Errorf("parsing age header: unexpected line: %q", line)
		}

		// Parse stanza header line
		parts := strings.Fields(strings.TrimPrefix(strings.TrimSuffix(line, "\n"), "-> "))
		if len(parts) == 0 {
			return nil, nil, fmt.Errorf("parsing age header: empty stanza")
		}
		s := &Stanza{
			Type: parts[0],
			Args: parts[1:],
		}

		// Read body lines
		var bodyLines []string
		for {
			bodyLine, err := r.ReadString('\n')
			if err != nil {
				return nil, nil, fmt.Errorf("parsing age header: unexpected EOF in stanza body")
			}
			headerBytes.WriteString(bodyLine)
			bodyLine = strings.TrimSuffix(bodyLine, "\n")
			bodyLines = append(bodyLines, bodyLine)
			if len(bodyLine) < 64 {
				break // Last line (shorter or empty)
			}
		}
		combined := strings.Join(bodyLines, "")
		s.Body, err = b64.DecodeString(combined)
		if err != nil {
			return nil, nil, fmt.Errorf("parsing age header: invalid base64 in stanza body: %w", err)
		}
		stanzas = append(stanzas, s)
	}
}

func tryDecryptFileKey(stanzas []*Stanza, identities []identity) ([]byte, error) {
	for _, id := range identities {
		for _, s := range stanzas {
			fileKey, err := id.unwrap(s)
			if err == nil {
				return fileKey, nil
			}
		}
	}
	return nil, fmt.Errorf("no identity matched any of the recipients")
}

func streamDecrypt(dst io.Writer, src io.Reader, fileKey []byte) error {
	// Read stream nonce
	nonce := make([]byte, 16)
	if _, err := io.ReadFull(src, nonce); err != nil {
		return fmt.Errorf("failed to read stream nonce: %w", err)
	}

	// Derive payload key
	payloadKey := make([]byte, 32)
	hkdfReader := hkdf.New(sha256.New, fileKey, nonce, []byte("payload"))
	if _, err := io.ReadFull(hkdfReader, payloadKey); err != nil {
		return err
	}

	aead, err := chacha20poly1305.New(payloadKey)
	if err != nil {
		return err
	}

	chunkNonce := make([]byte, 12)
	counter := uint64(0)
	// chunk overhead = 16 bytes poly1305 tag
	buf := make([]byte, chunkSize+16)

	for {
		// Try to read a full encrypted chunk
		n, readErr := io.ReadFull(src, buf)
		if readErr != nil && readErr != io.ErrUnexpectedEOF {
			if readErr == io.EOF && n == 0 {
				return fmt.Errorf("stream: unexpected end of encrypted data")
			}
			if readErr != io.EOF {
				return fmt.Errorf("stream: read error: %w", readErr)
			}
		}

		isLast := readErr == io.ErrUnexpectedEOF || readErr == io.EOF
		if !isLast && n == chunkSize+16 {
			// Check if there's more data (not the last chunk)
			// Actually we don't know if it's the last until we try the nonce
			// In STREAM, we use the is_last nonce bit
			// We need to try decrypting with is_last=0 first
			// If that fails and we're at EOF, try is_last=1
