			}

			return stanzas, fileKey, nil
		}

		headerBytes.WriteString(line)

		if !strings.HasPrefix(line, "-> ") {
			return nil, nil, fmt.Errorf("parsing age header: unexpected line: %q", line)
		}

		// Parse stanza header line
		parts := strings.Fields(strings.TrimPrefix(strings.TrimSuffix(line, "\n"), "-> "))
		if len(parts) == 0 {
			return nil, nil, fmt.Errorf("parsing age header: empty stanza")
