func streamDecrypt(dst io.Writer, src io.Reader, fileKey []byte) error {
	// Read stream nonce
	nonce := make([]byte, 16)
	if _, err := io.ReadFull(src, nonce); err != nil {
		return fmt.Errorf("failed to read stream nonce: %w", err)
	}

	// Derive payload key
	payloadKey := make([]byte, 32)
	hkdfReader := hkdf.New(sha256.New, fileKey, nonce, []byte("payload"))
	if _, err := io.ReadFull(hkdfReader, payloadKey); err != nil {
		return err
	}

	aead, err := chacha20poly1305.New(payloadKey)
	if err != nil {
		return err
	}

	chunkNonce := make([]byte, 12)
	counter := uint64(0)
	// chunk overhead = 16 bytes poly1305 tag
	buf := make([]byte, chunkSize+16)

	for {
		// Try to read a full encrypted chunk
		n, readErr := io.ReadFull(src, buf)
		if readErr != nil && readErr != io.ErrUnexpectedEOF {
			if readErr == io.EOF && n == 0 {
				return fmt.Errorf("stream: unexpected end of encrypted data")
			}
			if readErr != io.EOF {
				return fmt.Errorf("stream: read error: %w", readErr)
			}
		}

		isLast := readErr == io.ErrUnexpectedEOF || readErr == io.EOF
		if !isLast && n == chunkSize+16 {
			// Check if there's more data (not the last chunk)
			// Actually we don't know if it's the last until we try the nonce
			// In STREAM, we use the is_last nonce bit
			// We need to try decrypting with is_last=0 first
			// If that fails and we're at EOF, try is_last=1
		}

		setStreamChunkNonce(chunkNonce, counter, isLast)
		plaintext, err := aead.Open(nil, chunkNonce, buf[:n], nil)
		if err != nil {
			if !isLast {
				// Try with is_last=true (in case it's the actual last chunk)
				setStreamChunkNonce(chunkNonce, counter, true)
				plaintext, err = aead.Open(nil, chunkNonce, buf[:n], nil)
				if err != nil {
					return fmt.Errorf("stream: decryption failed at chunk %d: %w", counter, err)
				}
				if _, err := dst.Write(plaintext); err != nil {
					return err
				}
				return nil
			}
			return fmt.Errorf("stream: decryption failed at chunk %d: %w", counter, err)
		}
		if _, err := dst.Write(plaintext); err != nil {
			return err
		}
		if isLast {
			return nil
		}
		counter++
	}
}

// X25519 recipient

type x25519Recipient struct {
	publicKey []byte // 32 bytes
}

func (r *x25519Recipient) wrap(fileKey []byte) (*Stanza, error) {
	curve := ecdh.X25519()
	ephemeral, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		return nil, fmt.Errorf("x25519: failed to generate ephemeral key: %w", err)
	}

	recipPub, err := curve.NewPublicKey(r.publicKey)
	if err != nil {
		return nil, fmt.Errorf("x25519: invalid recipient public key: %w", err)
	}

	sharedSecret, err := ephemeral.ECDH(recipPub)
	if err != nil {
		return nil, fmt.Errorf("x25519: ECDH failed: %w", err)
	}

	ephemeralPub := ephemeral.PublicKey().Bytes()

	// salt = ephemeral_pubkey || recipient_pubkey
	salt := append(ephemeralPub, r.publicKey...)

	// Derive wrap key
	wrapKey := make([]byte, 32)
	hkdfReader := hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/X25519"))
	if _, err := io.ReadFull(hkdfReader, wrapKey); err != nil {
		return nil, err
	}

	// Encrypt file key
	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize()) // zero nonce
	wrappedKey := aead.Seal(nil, nonce, fileKey, nil)

	return &Stanza{
		Type: "X25519",
		Args: []string{b64.EncodeToString(ephemeralPub)},
		Body: wrappedKey,
	}, nil
}

type x25519Identity struct {
	privateKey []byte // 32 bytes
	publicKey  []byte // 32 bytes
}

func (id *x25519Identity) unwrap(s *Stanza) ([]byte, error) {
	if s.Type != "X25519" {
		return nil, fmt.Errorf("not an X25519 stanza")
	}
	if len(s.Args) != 1 {
		return nil, fmt.Errorf("x25519: expected 1 arg, got %d", len(s.Args))
	}

	ephemeralPub, err := b64.DecodeString(s.Args[0])
	if err != nil {
		return nil, fmt.Errorf("x25519: invalid ephemeral pubkey: %w", err)
	}
	if len(ephemeralPub) != 32 {
		return nil, fmt.Errorf("x25519: invalid ephemeral pubkey length")
	}

	curve := ecdh.X25519()
	ephemeralPubKey, err := curve.NewPublicKey(ephemeralPub)
	if err != nil {
		return nil, fmt.Errorf("x25519: invalid ephemeral pubkey: %w", err)
	}

	privKey, err := curve.NewPrivateKey(id.privateKey)
	if err != nil {
		return nil, fmt.Errorf("x25519: invalid private key: %w", err)
	}

	sharedSecret, err := privKey.ECDH(ephemeralPubKey)
	if err != nil {
		return nil, fmt.Errorf("x25519: ECDH failed: %w", err)
	}

	// salt = ephemeral_pubkey || recipient_pubkey (= our public key)
	salt := append(ephemeralPub, id.publicKey...)

	// Derive wrap key
	wrapKey := make([]byte, 32)
	hkdfReader := hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/X25519"))
	if _, err := io.ReadFull(hkdfReader, wrapKey); err != nil {
		return nil, err
	}

	// Decrypt file key
	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize()) // zero nonce
	fileKey, err := aead.Open(nil, nonce, s.Body, nil)
	if err != nil {
		return nil, fmt.Errorf("x25519: key decryption failed")
	}
	if len(fileKey) != fileKeySize {
		return nil, fmt.Errorf("x25519: unexpected file key length")
	}
	return fileKey, nil
}

// scrypt recipient

type scryptRecipient struct {
	passphrase []byte
	logN       int // default 18
}

func (r *scryptRecipient) wrap(fileKey []byte) (*Stanza, error) {
	salt := make([]byte, 16)
	if _, err := io.ReadFull(rand.Reader, salt); err != nil {
		return nil, fmt.Errorf("scrypt: failed to generate salt: %w", err)
	}

	logN := r.logN
	if logN <= 0 {
		logN = 18
	}

	// Derive key: scrypt(passphrase, "age-encryption.org/v1/scrypt" || salt, N=2^logN, r=8, p=1)
	label := append([]byte("age-encryption.org/v1/scrypt"), salt...)
	N := 1 << uint(logN)
	wrapKey, err := scryptKey(r.passphrase, label, N, 8, 1, 32)
	if err != nil {
		return nil, fmt.Errorf("scrypt: key derivation failed: %w", err)
	}

	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize()) // zero nonce
	wrappedKey := aead.Seal(nil, nonce, fileKey, nil)

	return &Stanza{
		Type: "scrypt",
		Args: []string{b64.EncodeToString(salt), strconv.Itoa(logN)},
		Body: wrappedKey,
	}, nil
}

type scryptIdentity struct {
	passphrase []byte
	maxWorkFactor int // max acceptable logN
}

func (id *scryptIdentity) unwrap(s *Stanza) ([]byte, error) {
	if s.Type != "scrypt" {
		return nil, fmt.Errorf("not a scrypt stanza")
	}
	if len(s.Args) != 2 {
		return nil, fmt.Errorf("scrypt: expected 2 args, got %d", len(s.Args))
	}

	salt, err := b64.DecodeString(s.Args[0])
	if err != nil {
		return nil, fmt.Errorf("scrypt: invalid salt: %w", err)
	}
	if len(salt) != 16 {
		return nil, fmt.Errorf("scrypt: invalid salt length")
	}

	logN, err := strconv.Atoi(s.Args[1])
	if err != nil {
		return nil, fmt.Errorf("scrypt: invalid work factor: %w", err)
	}

	maxWF := id.maxWorkFactor
	if maxWF <= 0 {
		maxWF = 30
	}
	if logN < 1 || logN > maxWF {
		return nil, fmt.Errorf("scrypt: work factor %d out of range [1, %d]", logN, maxWF)
	}

	label := append([]byte("age-encryption.org/v1/scrypt"), salt...)
	N := 1 << uint(logN)
	wrapKey, err := scryptKey(id.passphrase, label, N, 8, 1, 32)
	if err != nil {
		return nil, fmt.Errorf("scrypt: key derivation failed: %w", err)
	}

	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize()) // zero nonce
	fileKey, err := aead.Open(nil, nonce, s.Body, nil)
	if err != nil {
		return nil, fmt.Errorf("scrypt: key decryption failed (wrong passphrase?)")
	}
	if len(fileKey) != fileKeySize {
		return nil, fmt.Errorf("scrypt: unexpected file key length")
	}
	return fileKey, nil
}

// Interfaces for recipients and identities
type recipient interface {
	wrap(fileKey []byte) (*Stanza, error)
}

type identity interface {
	unwrap(s *Stanza) ([]byte, error)
}
