package main

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"io"
	"strings"
)

const (
	armorHeader = "-----BEGIN AGE ENCRYPTED FILE-----"
	armorFooter = "-----END AGE ENCRYPTED FILE-----"
)

// armorEncode wraps the data in PEM-like armor
func armorEncode(w io.Writer, data []byte) error {
	fmt.Fprintf(w, "%s\n", armorHeader)
	// Encode in standard base64 (with padding), 64 chars per line
	encoded := base64.StdEncoding.EncodeToString(data)
	for len(encoded) > 64 {
		fmt.Fprintf(w, "%s\n", encoded[:64])
		encoded = encoded[64:]
	}
	if len(encoded) > 0 {
		fmt.Fprintf(w, "%s\n", encoded)
	}
	fmt.Fprintf(w, "%s\n", armorFooter)
	return nil
}

// armorDecode removes the PEM-like armor and returns the raw data
func armorDecode(r io.Reader) ([]byte, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	s := strings.TrimSpace(string(data))

	if !strings.HasPrefix(s, armorHeader) {
		return nil, fmt.Errorf("armor: missing header")
	}
	s = strings.TrimPrefix(s, armorHeader)
	s = strings.TrimPrefix(s, "\n")

	if !strings.HasSuffix(s, armorFooter) {
		return nil, fmt.Errorf("armor: missing footer")
	}
	s = strings.TrimSuffix(s, armorFooter)
	s = strings.TrimRight(s, "\n")

	// Remove all newlines from the base64 data
	s = strings.ReplaceAll(s, "\n", "")
	s = strings.ReplaceAll(s, "\r", "")

	decoded, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		return nil, fmt.Errorf("armor: invalid base64: %w", err)
	}
	return decoded, nil
}

// armorWriter wraps an io.Writer to produce armored output
type armorWriter struct {
	buf bytes.Buffer
	w   io.Writer
}

func newArmorWriter(w io.Writer) *armorWriter {
	return &armorWriter{w: w}
}

func (aw *armorWriter) Write(p []byte) (n int, err error) {
	return aw.buf.Write(p)
}

func (aw *armorWriter) Close() error {
	return armorEncode(aw.w, aw.buf.Bytes())
}

// detectAndStripArmor detects if input is armored and returns a reader of the raw data
func detectAndStripArmor(r io.Reader) (io.Reader, bool, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, false, err
	}

	trimmed := strings.TrimSpace(string(data))
	if strings.HasPrefix(trimmed, armorHeader) {
		raw, err := armorDecode(bytes.NewReader(data))
		if err != nil {
			return nil, true, err
		}
		return bytes.NewReader(raw), true, nil
	}
	return bytes.NewReader(data), false, nil
}
