	"golang.org/x/crypto/hkdf"
	"crypto/sha256"
)

const version = "v0.0.0-20260414014000-96fce988442d"

func main() {
	if err := run(os.Args); err != nil {
		if err != errUsage {
			fmt.Fprintf(os.Stderr, "age: error: %s\n", err)
			fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
		}
		os.Exit(1)
	}
}

var errUsage = fmt.Errorf("usage error")

func printUsage(w io.Writer) {
	fmt.Fprintln(w, `Usage:
    age [--encrypt] (-r RECIPIENT | -R PATH)... [--armor] [-o OUTPUT] [INPUT]
    age [--encrypt] --passphrase [--armor] [-o OUTPUT] [INPUT]
    age --decrypt [-i PATH]... [-o OUTPUT] [INPUT]

Options:
    -e, --encrypt               Encrypt the input to the output. Default if omitted.
    -d, --decrypt               Decrypt the input to the output.
    -o, --output OUTPUT         Write the result to the file at path OUTPUT.
    -a, --armor                 Encrypt to a PEM encoded format.
    -p, --passphrase            Encrypt with a passphrase.
    -r, --recipient RECIPIENT   Encrypt to the specified RECIPIENT. Can be repeated.
    -R, --recipients-file PATH  Encrypt to recipients listed at PATH. Can be repeated.
    -i, --identity PATH         Use the identity file at PATH. Can be repeated.

INPUT defaults to standard input, and OUTPUT defaults to standard output.
If OUTPUT exists, it will be overwritten.

RECIPIENT can be an age public key generated by age-keygen ("age1...")
or an SSH public key ("ssh-ed25519 AAAA...", "ssh-rsa AAAA...").

Recipient files contain one or more recipients, one per line. Empty lines
and lines starting with "#" are ignored as comments. "-" may be used to
read recipients from standard input.

Identity files contain one or more secret keys ("AGE-SECRET-KEY-1..."),
one per line, or an SSH key. Empty lines and lines starting with "#" are
ignored as comments. Passphrase encrypted age files can be used as
identity files. Multiple key files can be provided, and any unused ones
will be ignored. "-" may be used to read identities from standard input.

When --encrypt is specified explicitly, -i can also be used to encrypt to an
identity file symmetrically, instead or in addition to normal recipients.

Example:
    $ age-keygen -o key.txt
    Public key: age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p
    $ tar cvz ~/data | age -r age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p > data.tar.gz.age
    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age`)
}

type args struct {
	encrypt     bool
	encryptExplicit bool
	decrypt     bool
	armor       bool
	passphrase  bool
	output      string
	recipients  []string
	recipFiles  []string
	identities  []string
	pluginNames []string // for -j
	input       string
}

func run(argv []string) error {
	a := &args{}

	// Parse arguments
	i := 1
	for i < len(argv) {
		arg := argv[i]
		switch {
		case arg == "--version":
			fmt.Println(version)
			return nil
		case arg == "--help" || arg == "-h":
			printUsage(os.Stdout)
			return nil
		case arg == "--encrypt" || arg == "-e":
			a.encrypt = true
			a.encryptExplicit = true
		case arg == "--decrypt" || arg == "-d":
			a.decrypt = true
		case arg == "--armor" || arg == "-a":
			a.armor = true
		case arg == "--passphrase" || arg == "-p":
			a.passphrase = true
		case arg == "--output" || arg == "-o":
			i++
			if i >= len(argv) {
				return fmt.Errorf("flag needs an argument: %s", arg)
			}
			a.output = argv[i]
		case strings.HasPrefix(arg, "--output="):
			a.output = arg[len("--output="):]
		case strings.HasPrefix(arg, "-o="):
			a.output = arg[len("-o="):]
		case arg == "--recipient" || arg == "-r":
			i++
			if i >= len(argv) {
				return fmt.Errorf("flag needs an argument: %s", arg)
			}
			a.recipients = append(a.recipients, argv[i])
		case strings.HasPrefix(arg, "--recipient="):
			a.recipients = append(a.recipients, arg[len("--recipient="):])
		case strings.HasPrefix(arg, "-r="):
			a.recipients = append(a.recipients, arg[len("-r="):])
		case arg == "--recipients-file" || arg == "-R":
			i++
			if i >= len(argv) {
				return fmt.Errorf("flag needs an argument: %s", arg)
			}
			a.recipFiles = append(a.recipFiles, argv[i])
		case strings.HasPrefix(arg, "--recipients-file="):
			a.recipFiles = append(a.recipFiles, arg[len("--recipients-file="):])
		case strings.HasPrefix(arg, "-R="):
			a.recipFiles = append(a.recipFiles, arg[len("-R="):])
		case arg == "--identity" || arg == "-i":
			i++
			if i >= len(argv) {
				return fmt.Errorf("flag needs an argument: %s", arg)
			}
			a.identities = append(a.identities, argv[i])
		case strings.HasPrefix(arg, "--identity="):
			a.identities = append(a.identities, arg[len("--identity="):])
		case strings.HasPrefix(arg, "-i="):
			a.identities = append(a.identities, arg[len("-i="):])
		case arg == "-j":
			i++
			if i >= len(argv) {
				return fmt.Errorf("flag needs an argument: %s", arg)
			}
			a.pluginNames = append(a.pluginNames, argv[i])
		case strings.HasPrefix(arg, "-"):
			return fmt.Errorf("unknown flag: %s", arg)
		default:
			// Input file
			if a.input != "" {
				return fmt.Errorf("too many INPUT arguments: %q %q\nhint: the input file must be specified after all flags\nhint: did you mean:\nhint:     %s --help %s", a.input, arg, argv[0], arg)
			}
			a.input = arg
		}
		i++
	}

	// Determine mode
	if a.decrypt && a.encrypt {
		return fmt.Errorf("flags --encrypt and --decrypt are mutually exclusive")
	}

	// Check for -j plugin
	if len(a.pluginNames) > 0 {
		return runWithPlugins(a)
	}

	if a.decrypt {
		return runDecrypt(a)
	}
	return runEncrypt(a)
}

func runEncrypt(a *args) error {
	// Check for mutually exclusive options
	if a.passphrase && (len(a.recipients) > 0 || len(a.recipFiles) > 0) {
		return fmt.Errorf("--passphrase is mutually exclusive with -r/--recipient and -R/--recipients-file")
	}
	if a.passphrase && len(a.identities) > 0 {
		return fmt.Errorf("--passphrase is mutually exclusive with -i/--identity")
	}

	// Check if we have any recipients
	hasRecipients := len(a.recipients) > 0 || len(a.recipFiles) > 0 || a.passphrase
	hasIdentitiesForEncrypt := len(a.identities) > 0 && a.encryptExplicit

	if !hasRecipients && !hasIdentitiesForEncrypt {
		fmt.Fprintf(os.Stderr, "age: error: missing recipients\n")
		fmt.Fprintf(os.Stderr, "age: hint: did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?\n")
		fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
		printUsage(os.Stderr)
		return errUsage
	}

	// Parse recipients
	var recipients []recipient

	for _, r := range a.recipients {
		recip, err := parseRecipient(r)
		if err != nil {
			return err
		}
		recipients = append(recipients, recip)
	}

	// Read recipient files
	for _, path := range a.recipFiles {
		var recipData io.Reader
		if path == "-" {
			if a.input == "" {
				return fmt.Errorf("recipients file is '-' but input is also stdin; specify INPUT file")
			}
			recipData = os.Stdin
		} else {
			f, err := os.Open(path)
			if err != nil {
				return fmt.Errorf("failed to open recipients file %q: %w", path, err)
			}
			defer f.Close()
			recipData = f
		}
		recips, err := parseRecipientsFile(recipData)
		if err != nil {
			return fmt.Errorf("failed to parse recipients file %q: %w", path, err)
		}
		recipients = append(recipients, recips...)
	}

	// Handle identity files in encrypt mode (only with -e explicit)
	if a.encryptExplicit {
		for _, path := range a.identities {
			var idData io.Reader
			if path == "-" {
				if a.input == "" {
					return fmt.Errorf("identity file is '-' but input is also stdin; specify INPUT file")
				}
				idData = os.Stdin
			} else {
				f, err := os.Open(path)
				if err != nil {
					return fmt.Errorf("failed to open identity file %q: %w", path, err)
				}
				defer f.Close()
				idData = f
			}
			// In encrypt mode with explicit -e, identity files are used to get recipients
			recips, err := parseIdentityFileForEncrypt(idData)
			if err != nil {
				return err
			}
			recipients = append(recipients, recips...)
		}
	}

	// Handle passphrase
	if a.passphrase {
		passphrase, err := readPassphraseForEncrypt()
		if err != nil {
			return err
		}
		recipients = append(recipients, &scryptRecipient{passphrase: passphrase})
	}

	if len(recipients) == 0 {
		return fmt.Errorf("missing recipients\nhint: did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?")
	}

	// Open input
	var input io.Reader
	if a.input == "" || a.input == "-" {
		input = os.Stdin
	} else {
		f, err := os.Open(a.input)
		if err != nil {
			return fmt.Errorf("failed to open input file %q: %w", a.input, err)
		}
		defer f.Close()
		input = f
	}

	// Open output
	var output io.WriteCloser
	if a.output == "" || a.output == "-" {
		// Check if outputting to terminal without armor
		if a.output == "" && !a.armor {
			// Check if stdout is a terminal
			if isTerminal(os.Stdout.Fd()) {
				return fmt.Errorf("refusing to output binary to a terminal\nhint: use -o to specify an output file, or pipe to another program, or use --armor for text output")
			}
		}
		output = os.Stdout
	} else {
		f, err := os.OpenFile(a.output, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
		if err != nil {
			return fmt.Errorf("failed to open output file %q: %w", a.output, err)
		}
		defer f.Close()
		output = f
	}

	var dst io.Writer = output
	var armorW *armorWriter
	if a.armor {
		armorW = newArmorWriter(output)
		dst = armorW
	}

	// Encrypt
	if err := ageEncrypt(dst, input, recipients, nil); err != nil {
		return fmt.Errorf("encryption failed: %w", err)
	}

	if armorW != nil {
		if err := armorW.Close(); err != nil {
			return fmt.Errorf("failed to write armor: %w", err)
		}
	}

	return nil
}

func runDecrypt(a *args) error {
	// Open input
	var inputReader io.Reader
	if a.input == "" || a.input == "-" {
		inputReader = os.Stdin
	} else {
		f, err := os.Open(a.input)
		if err != nil {
			return fmt.Errorf("failed to open input file %q: %w", a.input, err)
		}
		defer f.Close()
		inputReader = f
	}

	// Read all input first to detect armor
	rawInput, err := io.ReadAll(inputReader)
	if err != nil {
		return fmt.Errorf("failed to read input: %w", err)
	}

	// Detect and strip armor
	var decryptInput io.Reader
	if strings.HasPrefix(strings.TrimSpace(string(rawInput)), armorHeader) {
		stripped, err := armorDecode(bytes.NewReader(rawInput))
		if err != nil {
			return fmt.Errorf("failed to decode armor: %w", err)
		}
		decryptInput = bytes.NewReader(stripped)
	} else {
		decryptInput = bytes.NewReader(rawInput)
	}

	// Open output
	var output io.WriteCloser
	if a.output == "" || a.output == "-" {
		output = os.Stdout
	} else {
		f, err := os.OpenFile(a.output, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
		if err != nil {
			return fmt.Errorf("failed to open output file %q: %w", a.output, err)
		}
		defer f.Close()
		output = f
	}

	// Load identities
	var identities []identity

	for _, path := range a.identities {
		var idData []byte
		if path == "-" {
			if a.input == "" {
				return fmt.Errorf("identity file is '-' but input is also stdin; specify INPUT file")
			}
			idData, err = io.ReadAll(os.Stdin)
		} else {
			idData, err = os.ReadFile(path)
		}
		if err != nil {
			return fmt.Errorf("failed to read identity file %q: %w", path, err)
		}

		ids, err := parseIdentityFile(bytes.NewReader(idData), path)
		if err != nil {
			return err
		}
		identities = append(identities, ids...)
	}

	// If no identities provided, check if it's passphrase-encrypted (scrypt)
	// We need to peek at the header first
	headerData, err := peekHeader(decryptInput)
	if err != nil {
		return fmt.Errorf("failed to read header: %w", err)
	}

	isPassphraseFile := isScryptFile(headerData)

	if isPassphraseFile && len(identities) > 0 {
		return fmt.Errorf("passphrase-encrypted files cannot be decrypted with -i/--identity")
	}

	if isPassphraseFile {
		// Request passphrase
		passphrase, err := readPassphraseForDecrypt()
		if err != nil {
			return err
		}
		identities = []identity{&scryptIdentity{passphrase: passphrase, maxWorkFactor: 30}}
	}

	if len(identities) == 0 && !isPassphraseFile {
		return fmt.Errorf("no identities specified and file is not passphrase-encrypted\nhint: did you forget to specify -i/--identity?")
	}

	// Decrypt
	if err := ageDecrypt(output, bytes.NewReader(headerData), identities); err != nil {
		return err
	}

	return nil
}

func peekHeader(r io.Reader) ([]byte, error) {
	data, err := io.ReadAll(r)
	return data, err
}

func isScryptFile(data []byte) bool {
	// Check if the age file contains a scrypt stanza
	r := bufio.NewReader(bytes.NewReader(data))
	// Skip version line
	line, _ := r.ReadString('\n')
	if !strings.HasPrefix(line, ageHeader) {
		return false
	}
	for {
		line, err := r.ReadString('\n')
		if err != nil {
			return false
		}
		if strings.HasPrefix(line, "--- ") {
			return false
		}
		if strings.HasPrefix(line, "-> scrypt ") {
			return true
		}
	}
}

func readPassphraseForEncrypt() ([]byte, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	defer tty.Close()

	fmt.Fprintf(tty, "Enter passphrase (leave empty to autogenerate a secure one): ")
	passphrase, err := readLine(tty)
	if err != nil {
		return nil, fmt.Errorf("failed to read passphrase: %w", err)
	}
	fmt.Fprintln(tty)

	if len(passphrase) == 0 {
		// Auto-generate
		pass := generatePassphrase()
		fmt.Fprintf(os.Stderr, "age: using autogenerated passphrase %q\n", pass)
		return []byte(pass), nil
	}

	// Confirm passphrase
	fmt.Fprintf(tty, "Confirm passphrase: ")
	passphrase2, err := readLine(tty)
	if err != nil {
		return nil, fmt.Errorf("failed to read passphrase confirmation: %w", err)
	}
	fmt.Fprintln(tty)

	if string(passphrase) != string(passphrase2) {
		return nil, fmt.Errorf("passphrases don't match")
	}

	return passphrase, nil
}

func readPassphraseForDecrypt() ([]byte, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	defer tty.Close()

	fmt.Fprintf(tty, "Enter passphrase: ")
	passphrase, err := readLine(tty)
	if err != nil {
		return nil, fmt.Errorf("failed to read passphrase: %w", err)
	}
	fmt.Fprintln(tty)

	return passphrase, nil
}

func openTTY() (*os.File, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, err
	}
	return tty, nil
}

func readLine(f *os.File) ([]byte, error) {
	// Disable echo
	var oldState syscall.Termios
	if err := tcgetattr(f, &oldState); err == nil {
		newState := oldState
		newState.Lflag &^= syscall.ECHO
		tcsetattr(f, &newState)
		defer tcsetattr(f, &oldState)
	}

	var line []byte
	buf := make([]byte, 1)
	for {
		n, err := f.Read(buf)
		if n == 1 {
			if buf[0] == '\n' || buf[0] == '\r' {
				break
			}
			line = append(line, buf[0])
		}
		if err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
	}
	return line, nil
}

func generatePassphrase() string {
	// Generate a random passphrase using EFF word list approach
	// For simplicity, use a deterministic approach with random bytes
	words := []string{
		"abandon", "ability", "able", "about", "above", "absent", "absorb", "abstract",
		"absurd", "abuse", "access", "accident", "account", "accuse", "achieve", "acid",
		// This is a placeholder - real implementation would use EFF word list
	}
	_ = words

	// Generate 10 random words
	// This is simplified - real age uses EFF word list
	wordlist := effWordList()
	n := len(wordlist)

	var parts []string
	randBytes := make([]byte, 10*4)
	io.ReadFull(rand.Reader, randBytes)
	for i := 0; i < 10; i++ {
		idx := int(uint32(randBytes[i*4])<<24 | uint32(randBytes[i*4+1])<<16 | uint32(randBytes[i*4+2])<<8 | uint32(randBytes[i*4+3]))
		if idx < 0 {
			idx = -idx
		}
		parts = append(parts, wordlist[idx%n])
	}
	return strings.Join(parts, "-")
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func tcgetattr(f *os.File, t *syscall.Termios) error {
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(t)))
	if err != 0 {
		return err
	}
	return nil
}

func tcsetattr(f *os.File, t *syscall.Termios) error {
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), syscall.TCSETS, uintptr(unsafe.Pointer(t)))
	if err != 0 {
		return err
	}
	return nil
}

func parseRecipient(s string) (recipient, error) {
	s = strings.TrimSpace(s)

	if strings.HasPrefix(s, "age1pq") {
		// Post-quantum key - not supported in basic mode
		return nil, fmt.Errorf("post-quantum recipients require age v1.3.0+ with PQ support")
	}

	if strings.HasPrefix(s, "age1") {
		// X25519 age key
		hrp, pubKeyBytes, err := bech32Decode(s)
		if err != nil {
			return nil, fmt.Errorf("invalid age recipient: %w", err)
		}
		if hrp != "age" {
			return nil, fmt.Errorf("invalid age recipient: unexpected HRP %q", hrp)
		}
		if len(pubKeyBytes) != 32 {
			return nil, fmt.Errorf("invalid age recipient: unexpected key length %d", len(pubKeyBytes))
		}
		return &x25519Recipient{publicKey: pubKeyBytes}, nil
	}

	if strings.HasPrefix(s, "ssh-rsa ") || strings.HasPrefix(s, "ssh-ed25519 ") {
		// SSH public key
		return parseSSHRecipient(s)
	}

	return nil, fmt.Errorf("unknown recipient type: %q", s)
}

func parseSSHRecipient(s string) (recipient, error) {
	parts := strings.Fields(s)
	if len(parts) < 2 {
		return nil, fmt.Errorf("invalid SSH public key: %q", s)
	}

	keyType := parts[0]
	keyData, err := base64.StdEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("invalid SSH public key base64: %w", err)
	}

	pubKey, err := parseSSHPublicKey(keyData)
	if err != nil {
		return nil, fmt.Errorf("invalid SSH public key: %w", err)
	}

	if pubKey.keyType != keyType {
		return nil, fmt.Errorf("SSH key type mismatch")
	}

	switch keyType {
	case sshKeyTypeEd25519:
		return &sshEd25519Recipient{pubKey: pubKey}, nil
	case sshKeyTypeRSA:
		if pubKey.rsaN.BitLen() < 2048 {
			return nil, fmt.Errorf("SSH RSA key must be at least 2048 bits")
		}
		return &sshRSARecipient{pubKey: pubKey}, nil
	default:
		return nil, fmt.Errorf("unsupported SSH key type: %q", keyType)
	}
}

func parseRecipientsFile(r io.Reader) ([]recipient, error) {
	var recipients []recipient
	scanner := bufio.NewScanner(r)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		recip, err := parseRecipientLine(line)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: warning: skipping invalid recipient at line %d: %v\n", lineNum, err)
			continue
		}
		if recip != nil {
			recipients = append(recipients, recip)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return recipients, nil
}

func parseRecipientLine(line string) (recipient, error) {
	// Check for unsupported but valid SSH key types (skip with warning)
	if strings.HasPrefix(line, "ssh-") {
		parts := strings.Fields(line)
		if len(parts) < 2 {
			return nil, fmt.Errorf("invalid SSH public key")
		}
		keyType := parts[0]
		if keyType != sshKeyTypeRSA && keyType != sshKeyTypeEd25519 {
			// Unsupported but valid SSH key type - skip with warning
			return nil, nil
		}
	}
	return parseRecipient(line)
}

func parseIdentityFile(r io.Reader, path string) ([]identity, error) {
	var identities []identity
	scanner := bufio.NewScanner(r)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		id, err := parseIdentityLine(trimmed, path)
		if err != nil {
			return nil, fmt.Errorf("error at line %d: %w", lineNum, err)
		}
		if id != nil {
			identities = append(identities, id)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return identities, nil
}

func parseIdentityLine(line string, path string) (identity, error) {
	if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
		// X25519 private key
		hrp, privKeyBytes, err := bech32Decode(line)
		if err != nil {
			return nil, fmt.Errorf("malformed secret key: %w", err)
		}
		if hrp != "age-secret-key-" {
			return nil, fmt.Errorf("malformed secret key: unexpected HRP %q", hrp)
		}
		if len(privKeyBytes) != 32 {
			return nil, fmt.Errorf("malformed secret key: unexpected key length %d", len(privKeyBytes))
		}

		// Derive public key
		curve := ecdh.X25519()
		privKey, err := curve.NewPrivateKey(privKeyBytes)
		if err != nil {
			return nil, fmt.Errorf("malformed secret key: %w", err)
		}
		pubKeyBytes := privKey.PublicKey().Bytes()

		return &x25519Identity{
			privateKey: privKeyBytes,
			publicKey:  pubKeyBytes,
		}, nil
	}

	// SSH private key - would need to handle OpenSSH private key format
	// For now, skip
	return nil, fmt.Errorf("unknown identity type")
}

func parseIdentityFileForEncrypt(r io.Reader) ([]recipient, error) {
	// Convert identity file to recipients
	var recipients []recipient
	scanner := bufio.NewScanner(r)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
			hrp, privKeyBytes, err := bech32Decode(line)
			if err != nil {
				return nil, fmt.Errorf("malformed secret key: %w", err)
			}
			if hrp != "age-secret-key-" {
				return nil, fmt.Errorf("malformed secret key: unexpected HRP %q", hrp)
			}

			curve := ecdh.X25519()
			privKey, err := curve.NewPrivateKey(privKeyBytes)
			if err != nil {
				return nil, fmt.Errorf("malformed secret key: %w", err)
			}
			pubKeyBytes := privKey.PublicKey().Bytes()
			recipients = append(recipients, &x25519Recipient{publicKey: pubKeyBytes})
		}
	}
	return recipients, nil
}

func runWithPlugins(a *args) error {
	// Handle -j plugin names
	for _, name := range a.pluginNames {
		return fmt.Errorf("failed to wrap key for recipient #0: %s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH\nhint: you might want to install the %q plugin\nhint: visit https://age-encryption.org/awesome#plugins for a list of available plugins", name, name, "age-plugin-"+name, name)
	}
	return nil
}

