	var input io.Reader
	if a.input == "" || a.input == "-" {
		input = os.Stdin
	} else {
		f, err := os.Open(a.input)
		if err != nil {
			return fmt.Errorf("failed to open input file %q: %w", a.input, err)
		}
		defer f.Close()
		input = f
	}

