	}

	if armorW != nil {
		if err := armorW.Close(); err != nil {
			return fmt.Errorf("failed to write armor: %w", err)
		}
	}

	return nil
}

func runDecrypt(a *args) error {
	// Open input
	var inputReader io.Reader
	if a.input == "" || a.input == "-" {
		inputReader = os.Stdin
	} else {
		f, err := os.Open(a.input)
		if err != nil {
			return fmt.Errorf("failed to open input file %q: %w", a.input, err)
		}
		defer f.Close()
		inputReader = f
	}

	// Read all input first to detect armor
	rawInput, err := io.ReadAll(inputReader)
	if err != nil {
		return fmt.Errorf("failed to read input: %w", err)
	}

	// Detect and strip armor
	var decryptInput io.Reader
	if strings.HasPrefix(strings.TrimSpace(string(rawInput)), armorHeader) {
		stripped, err := armorDecode(bytes.NewReader(rawInput))
		if err != nil {
			return fmt.Errorf("failed to decode armor: %w", err)
		}
		decryptInput = bytes.NewReader(stripped)
	} else {
		decryptInput = bytes.NewReader(rawInput)
	}

	// Open output
	var output io.WriteCloser
	if a.output == "" || a.output == "-" {
		output = os.Stdout
	} else {
		f, err := os.OpenFile(a.output, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
		if err != nil {
			return fmt.Errorf("failed to open output file %q: %w", a.output, err)
		}
		defer f.Close()
		output = f
	}

	// Load identities
	var identities []identity

	for _, path := range a.identities {
		var idData []byte
		if path == "-" {
			if a.input == "" {
				return fmt.Errorf("identity file is '-' but input is also stdin; specify INPUT file")
			}
			idData, err = io.ReadAll(os.Stdin)
		} else {
			idData, err = os.ReadFile(path)
		}
		if err != nil {
			return fmt.Errorf("failed to read identity file %q: %w", path, err)
		}

		ids, err := parseIdentityFile(bytes.NewReader(idData), path)
		if err != nil {
			return err
		}
		identities = append(identities, ids...)
	}

	// If no identities provided, check if it's passphrase-encrypted (scrypt)
	// We need to peek at the header first
	headerData, err := peekHeader(decryptInput)
	if err != nil {
		return fmt.Errorf("failed to read header: %w", err)
	}

	isPassphraseFile := isScryptFile(headerData)

	if isPassphraseFile && len(identities) > 0 {
		return fmt.Errorf("passphrase-encrypted files cannot be decrypted with -i/--identity")
	}

	if isPassphraseFile {
		// Request passphrase
		passphrase, err := readPassphraseForDecrypt()
		if err != nil {
			return err
		}
		identities = []identity{&scryptIdentity{passphrase: passphrase, maxWorkFactor: 30}}
	}

	if len(identities) == 0 && !isPassphraseFile {
		return fmt.Errorf("no identities specified and file is not passphrase-encrypted\nhint: did you forget to specify -i/--identity?")
	}

	// Decrypt
	if err := ageDecrypt(output, bytes.NewReader(headerData), identities); err != nil {
		return err
	}

	return nil
}

func peekHeader(r io.Reader) ([]byte, error) {
	data, err := io.ReadAll(r)
	return data, err
}

func isScryptFile(data []byte) bool {
	// Check if the age file contains a scrypt stanza
	r := bufio.NewReader(bytes.NewReader(data))
	// Skip version line
	line, _ := r.ReadString('\n')
	if !strings.HasPrefix(line, ageHeader) {
		return false
	}
	for {
		line, err := r.ReadString('\n')
		if err != nil {
			return false
		}
		if strings.HasPrefix(line, "--- ") {
			return false
		}
		if strings.HasPrefix(line, "-> scrypt ") {
			return true
		}
	}
}

func readPassphraseForEncrypt() ([]byte, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	defer tty.Close()

	fmt.Fprintf(tty, "Enter passphrase (leave empty to autogenerate a secure one): ")
	passphrase, err := readLine(tty)
	if err != nil {
		return nil, fmt.Errorf("failed to read passphrase: %w", err)
	}
	fmt.Fprintln(tty)

	if len(passphrase) == 0 {
		// Auto-generate
		pass := generatePassphrase()
		fmt.Fprintf(os.Stderr, "age: using autogenerated passphrase %q\n", pass)
		return []byte(pass), nil
	}

	// Confirm passphrase
	fmt.Fprintf(tty, "Confirm passphrase: ")
	passphrase2, err := readLine(tty)
	if err != nil {
		return nil, fmt.Errorf("failed to read passphrase confirmation: %w", err)
	}
	fmt.Fprintln(tty)

	if string(passphrase) != string(passphrase2) {
		return nil, fmt.Errorf("passphrases don't match")
	}

	return passphrase, nil
}

func readPassphraseForDecrypt() ([]byte, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	defer tty.Close()

	fmt.Fprintf(tty, "Enter passphrase: ")
	passphrase, err := readLine(tty)
	if err != nil {
		return nil, fmt.Errorf("failed to read passphrase: %w", err)
	}
	fmt.Fprintln(tty)

	return passphrase, nil
}

func openTTY() (*os.File, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, err
	}
	return tty, nil
}

func readLine(f *os.File) ([]byte, error) {
	// Disable echo
	var oldState syscall.Termios
	if err := tcgetattr(f, &oldState); err == nil {
		newState := oldState
		newState.Lflag &^= syscall.ECHO
		tcsetattr(f, &newState)
		defer tcsetattr(f, &oldState)
	}

	var line []byte
	buf := make([]byte, 1)
	for {
		n, err := f.Read(buf)
		if n == 1 {
			if buf[0] == '\n' || buf[0] == '\r' {
				break
			}
			line = append(line, buf[0])
		}
		if err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
	}
	return line, nil
}

func generatePassphrase() string {
	// Generate a random passphrase using EFF word list approach
	// For simplicity, use a deterministic approach with random bytes
	words := []string{
		"abandon", "ability", "able", "about", "above", "absent", "absorb", "abstract",
		"absurd", "abuse", "access", "accident", "account", "accuse", "achieve", "acid",
		// This is a placeholder - real implementation would use EFF word list
	}
	_ = words

	// Generate 10 random words
	// This is simplified - real age uses EFF word list
	wordlist := effWordList()
	n := len(wordlist)

	var parts []string
	randBytes := make([]byte, 10*4)
	io.ReadFull(rand.Reader, randBytes)
	for i := 0; i < 10; i++ {
		idx := int(uint32(randBytes[i*4])<<24 | uint32(randBytes[i*4+1])<<16 | uint32(randBytes[i*4+2])<<8 | uint32(randBytes[i*4+3]))
		if idx < 0 {
			idx = -idx
		}
		parts = append(parts, wordlist[idx%n])
	}
	return strings.Join(parts, "-")
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func tcgetattr(f *os.File, t *syscall.Termios) error {
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(t)))
	if err != 0 {
		return err
	}
	return nil
}

func tcsetattr(f *os.File, t *syscall.Termios) error {
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), syscall.TCSETS, uintptr(unsafe.Pointer(t)))
	if err != 0 {
		return err
	}
	return nil
}

func parseRecipient(s string) (recipient, error) {
	s = strings.TrimSpace(s)

	if strings.HasPrefix(s, "age1pq") {
		// Post-quantum key - not supported in basic mode
		return nil, fmt.Errorf("post-quantum recipients require age v1.3.0+ with PQ support")
	}

	if strings.HasPrefix(s, "age1") {
		// X25519 age key
		hrp, pubKeyBytes, err := bech32Decode(s)
		if err != nil {
			return nil, fmt.Errorf("invalid age recipient: %w", err)
		}
		if hrp != "age" {
			return nil, fmt.Errorf("invalid age recipient: unexpected HRP %q", hrp)
		}
		if len(pubKeyBytes) != 32 {
			return nil, fmt.Errorf("invalid age recipient: unexpected key length %d", len(pubKeyBytes))
		}
		return &x25519Recipient{publicKey: pubKeyBytes}, nil
	}

	if strings.HasPrefix(s, "ssh-rsa ") || strings.HasPrefix(s, "ssh-ed25519 ") {
		// SSH public key
		return parseSSHRecipient(s)
	}

	return nil, fmt.Errorf("unknown recipient type: %q", s)
}

func parseSSHRecipient(s string) (recipient, error) {
	parts := strings.Fields(s)
	if len(parts) < 2 {
		return nil, fmt.Errorf("invalid SSH public key: %q", s)
	}

	keyType := parts[0]
	keyData, err := base64.StdEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("invalid SSH public key base64: %w", err)
	}

	pubKey, err := parseSSHPublicKey(keyData)
	if err != nil {
		return nil, fmt.Errorf("invalid SSH public key: %w", err)
	}

	if pubKey.keyType != keyType {
		return nil, fmt.Errorf("SSH key type mismatch")
	}

	switch keyType {
	case sshKeyTypeEd25519:
		return &sshEd25519Recipient{pubKey: pubKey}, nil
	case sshKeyTypeRSA:
		if pubKey.rsaN.BitLen() < 2048 {
			return nil, fmt.Errorf("SSH RSA key must be at least 2048 bits")
		}
		return &sshRSARecipient{pubKey: pubKey}, nil
	default:
		return nil, fmt.Errorf("unsupported SSH key type: %q", keyType)
	}
}

func parseRecipientsFile(r io.Reader) ([]recipient, error) {
	var recipients []recipient
	scanner := bufio.NewScanner(r)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		recip, err := parseRecipientLine(line)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: warning: skipping invalid recipient at line %d: %v\n", lineNum, err)
			continue
		}
		if recip != nil {
			recipients = append(recipients, recip)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return recipients, nil
}

func parseRecipientLine(line string) (recipient, error) {
	// Check for unsupported but valid SSH key types (skip with warning)
	if strings.HasPrefix(line, "ssh-") {
		parts := strings.Fields(line)
		if len(parts) < 2 {
			return nil, fmt.Errorf("invalid SSH public key")
		}
		keyType := parts[0]
		if keyType != sshKeyTypeRSA && keyType != sshKeyTypeEd25519 {
			// Unsupported but valid SSH key type - skip with warning
			return nil, nil
		}
	}
	return parseRecipient(line)
}

func parseIdentityFile(r io.Reader, path string) ([]identity, error) {
	var identities []identity
	scanner := bufio.NewScanner(r)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		id, err := parseIdentityLine(trimmed, path)
		if err != nil {
			return nil, fmt.Errorf("error at line %d: %w", lineNum, err)
		}
		if id != nil {
			identities = append(identities, id)
		}
