func parseIdentityLine(line string, path string) (identity, error) {
	if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
		// X25519 private key
		hrp, privKeyBytes, err := bech32Decode(line)
		if err != nil {
			return nil, fmt.Errorf("malformed secret key: %w", err)
		}
		if hrp != "age-secret-key-" {
			return nil, fmt.Errorf("malformed secret key: unexpected HRP %q", hrp)
		}
		if len(privKeyBytes) != 32 {
			return nil, fmt.Errorf("malformed secret key: unexpected key length %d", len(privKeyBytes))
		}

		// Derive public key
		curve := ecdh.X25519()
		privKey, err := curve.NewPrivateKey(privKeyBytes)
		if err != nil {
			return nil, fmt.Errorf("malformed secret key: %w", err)
		}
		pubKeyBytes := privKey.PublicKey().Bytes()

		return &x25519Identity{
			privateKey: privKeyBytes,
			publicKey:  pubKeyBytes,
		}, nil
	}

	// SSH private key - would need to handle OpenSSH private key format
	// For now, skip
	return nil, fmt.Errorf("unknown identity type")
}

func parseIdentityFileForEncrypt(r io.Reader) ([]recipient, error) {
