package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
)

// scryptDeriveKey implements the scrypt password-based KDF (RFC 7914).
func scryptDeriveKey(password, salt []byte, N, r, p, keyLen int) ([]byte, error) {
	if N <= 1 || (N&(N-1)) != 0 {
		return nil, fmt.Errorf("scrypt: N must be > 1 and a power of 2")
	}
	if r <= 0 {
		return nil, fmt.Errorf("scrypt: invalid r")
	}
	if p <= 0 {
		return nil, fmt.Errorf("scrypt: invalid p")
	}

	xy := make([]uint32, 64*r)
	v := make([]uint32, 32*N*r)
	B := pbkdf2SHA256(password, salt, 1, p*128*r)

	for i := 0; i < p; i++ {
		smix(B[i*128*r:(i+1)*128*r], r, N, v, xy)
	}

	return pbkdf2SHA256(password, B, 1, keyLen), nil
}

func smix(b []byte, r, N int, v, xy []uint32) {
	x := xy[:32*r]
	y := xy[32*r:]

	for i := 0; i < 32*r; i++ {
		x[i] = binary.LittleEndian.Uint32(b[4*i:])
	}

	for i := 0; i < N; i++ {
		copy(v[i*32*r:], x[:32*r])
		blockMixSalsa(x, y, r)
	}

	for i := 0; i < N; i++ {
		j := int(x[(2*r-1)*16] & uint32(N-1))
		for k := 0; k < 32*r; k++ {
			x[k] ^= v[j*32*r+k]
		}
		blockMixSalsa(x, y, r)
	}

	for i := 0; i < 32*r; i++ {
		binary.LittleEndian.PutUint32(b[4*i:], x[i])
	}
}

func blockMixSalsa(x, y []uint32, r int) {
	var t [16]uint32
	copy(t[:], x[(2*r-1)*16:])
	for i := 0; i < 2*r; i++ {
		for j := 0; j < 16; j++ {
			t[j] ^= x[i*16+j]
		}
		salsa20Core(&t)
		copy(y[i*16:], t[:])
	}
	for i := 0; i < r; i++ {
		copy(x[i*16:], y[2*i*16:(2*i+1)*16])
	}
	for i := 0; i < r; i++ {
		copy(x[(r+i)*16:], y[(2*i+1)*16:(2*i+2)*16])
	}
}

func salsa20Core(x *[16]uint32) {
	a := *x
	for round := 0; round < 4; round++ {
		// Column rounds
		a[4] ^= rotl32(a[0]+a[12], 7)
		a[8] ^= rotl32(a[4]+a[0], 9)
		a[12] ^= rotl32(a[8]+a[4], 13)
		a[0] ^= rotl32(a[12]+a[8], 18)

		a[9] ^= rotl32(a[5]+a[1], 7)
		a[13] ^= rotl32(a[9]+a[5], 9)
		a[1] ^= rotl32(a[13]+a[9], 13)
		a[5] ^= rotl32(a[1]+a[13], 18)

		a[14] ^= rotl32(a[10]+a[6], 7)
		a[2] ^= rotl32(a[14]+a[10], 9)
		a[6] ^= rotl32(a[2]+a[14], 13)
		a[10] ^= rotl32(a[6]+a[2], 18)

		a[3] ^= rotl32(a[15]+a[11], 7)
		a[7] ^= rotl32(a[3]+a[15], 9)
		a[11] ^= rotl32(a[7]+a[3], 13)
		a[15] ^= rotl32(a[11]+a[7], 18)

		// Row rounds
		a[1] ^= rotl32(a[0]+a[3], 7)
		a[2] ^= rotl32(a[1]+a[0], 9)
		a[3] ^= rotl32(a[2]+a[1], 13)
		a[0] ^= rotl32(a[3]+a[2], 18)

		a[6] ^= rotl32(a[5]+a[4], 7)
		a[7] ^= rotl32(a[6]+a[5], 9)
		a[4] ^= rotl32(a[7]+a[6], 13)
		a[5] ^= rotl32(a[4]+a[7], 18)

		a[11] ^= rotl32(a[10]+a[9], 7)
		a[8] ^= rotl32(a[11]+a[10], 9)
		a[9] ^= rotl32(a[8]+a[11], 13)
		a[10] ^= rotl32(a[9]+a[8], 18)

		a[12] ^= rotl32(a[15]+a[14], 7)
		a[13] ^= rotl32(a[12]+a[15], 9)
		a[14] ^= rotl32(a[13]+a[12], 13)
		a[15] ^= rotl32(a[14]+a[13], 18)
	}
	for i := range x {
		x[i] += a[i]
	}
}

func rotl32(v uint32, n uint) uint32 {
	return (v << n) | (v >> (32 - n))
}

// pbkdf2SHA256 implements PBKDF2 with HMAC-SHA256 (RFC 2898).
func pbkdf2SHA256(password, salt []byte, iter, keyLen int) []byte {
	hashLen := sha256.Size
	numBlocks := (keyLen + hashLen - 1) / hashLen
	dk := make([]byte, numBlocks*hashLen)
	blockNum := make([]byte, 4)

	for i := 1; i <= numBlocks; i++ {
		binary.BigEndian.PutUint32(blockNum, uint32(i))
		h := hmac.New(sha256.New, password)
		h.Write(salt)
		h.Write(blockNum)
		U := h.Sum(nil)
		T := make([]byte, hashLen)
		copy(T, U)
		for j := 1; j < iter; j++ {
			h = hmac.New(sha256.New, password)
			h.Write(U)
			U = h.Sum(nil)
			for k := range T {
				T[k] ^= U[k]
			}
		}
		copy(dk[(i-1)*hashLen:], T)
	}
	return dk[:keyLen]
}
