package main

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"io"
	"strings"
)

const (
	armorBegin = "-----BEGIN AGE ENCRYPTED FILE-----"
	armorEnd   = "-----END AGE ENCRYPTED FILE-----"
)

// armorWriter buffers data and writes it in PEM-like armor format when closed.
type armorWriter struct {
	buf bytes.Buffer
	w   io.Writer
}

func newArmorWriter(w io.Writer) *armorWriter {
	return &armorWriter{w: w}
}

func (aw *armorWriter) Write(p []byte) (n int, err error) {
	return aw.buf.Write(p)
}

func (aw *armorWriter) Close() error {
	data := aw.buf.Bytes()
	// Encode with standard base64 WITH padding, 64 chars per line
	encoded := base64.StdEncoding.EncodeToString(data)
	fmt.Fprintf(aw.w, "%s\n", armorBegin)
	for len(encoded) > 64 {
		fmt.Fprintf(aw.w, "%s\n", encoded[:64])
		encoded = encoded[64:]
	}
	if len(encoded) > 0 {
		fmt.Fprintf(aw.w, "%s\n", encoded)
	}
	fmt.Fprintf(aw.w, "%s\n", armorEnd)
	return nil
}

// decodeArmor decodes a PEM-like armored age file.
func decodeArmor(data []byte) ([]byte, error) {
	s := strings.TrimSpace(string(data))
	if !strings.HasPrefix(s, armorBegin) {
		return nil, fmt.Errorf("missing armor header")
	}
	s = strings.TrimPrefix(s, armorBegin)
	if !strings.HasSuffix(s, armorEnd) {
		return nil, fmt.Errorf("missing armor footer")
	}
	s = strings.TrimSuffix(s, armorEnd)
	s = strings.TrimSpace(s)
	// Remove all newlines
	s = strings.ReplaceAll(s, "\r\n", "")
	s = strings.ReplaceAll(s, "\n", "")
	s = strings.ReplaceAll(s, "\r", "")
	decoded, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		return nil, fmt.Errorf("invalid base64 in armor: %w", err)
	}
	return decoded, nil
}

// isArmored returns true if data starts with the armor header.
func isArmored(data []byte) bool {
	return bytes.HasPrefix(bytes.TrimSpace(data), []byte(armorBegin))
}
