package main

import (
	"bufio"
	"bytes"
	"crypto/ecdh"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"io"
	"strconv"
	"strings"

	"golang.org/x/crypto/chacha20poly1305"
	"golang.org/x/crypto/hkdf"
)

const (
	ageFormatHeader = "age-encryption.org/v1"
	ageFileKeySize  = 16
	ageChunkSize    = 65536 // 64 KiB
)

// b64std is standard base64 without padding.
var b64std = base64.RawStdEncoding

// Stanza represents a recipient stanza in an age header.
type Stanza struct {
	Type string
	Args []string
	Body []byte
}

// Recipient can wrap (encrypt) a file key.
type Recipient interface {
	WrapKey(fileKey []byte) (*Stanza, error)
}

// Identity can unwrap (decrypt) a file key from a stanza.
type Identity interface {
	UnwrapKey(stanza *Stanza) ([]byte, error)
}

// EncryptAge encrypts src to dst using the given recipients.
func EncryptAge(dst io.Writer, src io.Reader, recipients []Recipient) error {
	// Generate random file key
	fileKey := make([]byte, ageFileKeySize)
	if _, err := io.ReadFull(rand.Reader, fileKey); err != nil {
		return fmt.Errorf("failed to generate file key: %w", err)
	}

	// Wrap file key for each recipient
	var stanzas []*Stanza
	for i, r := range recipients {
		s, err := r.WrapKey(fileKey)
		if err != nil {
			return fmt.Errorf("failed to wrap key for recipient #%d: %w", i, err)
		}
		stanzas = append(stanzas, s)
	}

	// Write header to a buffer first (for MAC computation)
	var headerBuf bytes.Buffer
	fmt.Fprintf(&headerBuf, "%s\n", ageFormatHeader)
	for _, s := range stanzas {
		writeStanza(&headerBuf, s)
	}

	// Compute header MAC
	macKey := make([]byte, 32)
	if _, err := io.ReadFull(hkdf.New(sha256.New, fileKey, nil, []byte("header")), macKey); err != nil {
		return err
	}
	mac := hmac.New(sha256.New, macKey)
	mac.Write(headerBuf.Bytes())
	macBytes := mac.Sum(nil)

	// Write header + MAC line
	fmt.Fprintf(&headerBuf, "--- %s\n", b64std.EncodeToString(macBytes))

	// Write header to output
	if _, err := dst.Write(headerBuf.Bytes()); err != nil {
		return fmt.Errorf("failed to write header: %w", err)
	}

	// Encrypt payload
	return streamEncrypt(dst, src, fileKey)
}

func writeStanza(w io.Writer, s *Stanza) {
	args := append([]string{s.Type}, s.Args...)
	fmt.Fprintf(w, "-> %s\n", strings.Join(args, " "))
	// Body in 48-byte chunks → 64 base64 chars per line
	encoded := b64std.EncodeToString(s.Body)
	for len(encoded) > 64 {
		fmt.Fprintf(w, "%s\n", encoded[:64])
		encoded = encoded[64:]
	}
	// Always write the last (possibly empty) line
	fmt.Fprintf(w, "%s\n", encoded)
}

// DecryptAge decrypts src to dst using the given identities.
func DecryptAge(dst io.Writer, src io.Reader, identities []Identity) error {
	r := bufio.NewReader(src)

	// Parse header and recover file key
	fileKey, err := parseHeader(r, identities)
	if err != nil {
		return err
	}

	// Decrypt payload
	return streamDecrypt(dst, r, fileKey)
}

func parseHeader(r *bufio.Reader, identities []Identity) ([]byte, error) {
	// Read version line
	versionLine, err := r.ReadString('\n')
	if err != nil {
		return nil, fmt.Errorf("parsing age header: failed to read header: %w", err)
	}
	if strings.TrimSuffix(versionLine, "\n") != ageFormatHeader {
		return nil, fmt.Errorf("parsing age header: unexpected intro: %q", versionLine)
	}

	// Track header bytes for MAC
	var headerBuf bytes.Buffer
	headerBuf.WriteString(versionLine)

	var stanzas []*Stanza

	for {
		line, err := r.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				return nil, fmt.Errorf("failed to parse header: failed to read line: %w", io.EOF)
			}
			return nil, fmt.Errorf("failed to parse header: failed to read line: %w", err)
		}

		if strings.HasPrefix(line, "--- ") {
			// End of header
			macStr := strings.TrimSpace(line[4:])
			expectedMAC, err := b64std.DecodeString(macStr)
			if err != nil {
				return nil, fmt.Errorf("failed to parse header: invalid MAC encoding: %w", err)
			}
			if len(expectedMAC) != 32 {
				return nil, fmt.Errorf("failed to parse header: invalid MAC length %d", len(expectedMAC))
			}

			// Unwrap file key
			fileKey, err := unwrapFileKey(stanzas, identities)
			if err != nil {
				return nil, err
			}

			// Verify MAC
			macKey := make([]byte, 32)
			if _, err := io.ReadFull(hkdf.New(sha256.New, fileKey, nil, []byte("header")), macKey); err != nil {
				return nil, err
			}
			mac := hmac.New(sha256.New, macKey)
			mac.Write(headerBuf.Bytes())
			if !hmac.Equal(mac.Sum(nil), expectedMAC) {
				return nil, fmt.Errorf("failed to authenticate the header")
			}

			return fileKey, nil
		}

		headerBuf.WriteString(line)

		if !strings.HasPrefix(line, "-> ") {
			return nil, fmt.Errorf("failed to parse header: malformed stanza opening line: %q", line)
		}

		// Parse stanza header
		stanzaHeader := strings.TrimSuffix(line, "\n")
		stanzaHeader = strings.TrimPrefix(stanzaHeader, "-> ")
		parts := strings.Fields(stanzaHeader)
		if len(parts) == 0 {
			return nil, fmt.Errorf("failed to parse header: empty stanza type")
		}
		s := &Stanza{
			Type: parts[0],
			Args: parts[1:],
		}

		// Read body lines
		var bodyParts []string
		for {
			bodyLine, err := r.ReadString('\n')
			if err != nil {
				return nil, fmt.Errorf("failed to parse header: failed to read line: %w", err)
			}
			headerBuf.WriteString(bodyLine)
			bodyLine = strings.TrimSuffix(bodyLine, "\n")
			// Validate: base64 characters only
			_, decErr := b64std.DecodeString(bodyLine)
			if decErr != nil {
				return nil, fmt.Errorf("failed to parse header: parsing age header: malformed body line %q: %w", bodyLine+"\n", decErr)
			}
			bodyParts = append(bodyParts, bodyLine)
			if len(bodyLine) < 64 {
				break // Last line (shorter than 64 chars)
			}
		}
		combined := strings.Join(bodyParts, "")
		s.Body, _ = b64std.DecodeString(combined) // already validated above
		stanzas = append(stanzas, s)
	}
}

func unwrapFileKey(stanzas []*Stanza, identities []Identity) ([]byte, error) {
	for _, id := range identities {
		for _, s := range stanzas {
			fileKey, err := id.UnwrapKey(s)
			if err == nil && fileKey != nil {
				return fileKey, nil
			}
		}
	}
	return nil, fmt.Errorf("no identity matched any of the recipients")
}

// streamEncrypt encrypts src to dst using STREAM cipher with fileKey.
func streamEncrypt(dst io.Writer, src io.Reader, fileKey []byte) error {
	// Generate stream nonce
	streamNonce := make([]byte, 16)
	if _, err := io.ReadFull(rand.Reader, streamNonce); err != nil {
		return fmt.Errorf("failed to generate stream nonce: %w", err)
	}

	// Derive payload key
	payloadKey := make([]byte, 32)
	if _, err := io.ReadFull(hkdf.New(sha256.New, fileKey, streamNonce, []byte("payload")), payloadKey); err != nil {
		return err
	}

	aead, err := chacha20poly1305.New(payloadKey)
	if err != nil {
		return err
	}

	if _, err := dst.Write(streamNonce); err != nil {
		return err
	}

	buf := make([]byte, ageChunkSize)
	chunkNonce := make([]byte, 12)
	counter := uint32(0)

	for {
		n, readErr := io.ReadFull(src, buf)
