	}

	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize())
	wrappedKey := aead.Seal(nil, nonce, fileKey, nil)

	return &Stanza{
		Type: "scrypt",
		Args: []string{b64std.EncodeToString(salt), strconv.Itoa(logN)},
		Body: wrappedKey,
	}, nil
}

// ScryptIdentity unwraps a file key with scrypt passphrase.
type ScryptIdentity struct {
	Passphrase    []byte
	MaxWorkFactor int // max acceptable logN (default 30)
}

func (id *ScryptIdentity) UnwrapKey(s *Stanza) ([]byte, error) {
	if s.Type != "scrypt" {
		return nil, errNotMyStanza
