	if maxWF <= 0 {
		maxWF = 30
	}
	if logN < 1 || logN > maxWF {
		return nil, fmt.Errorf("scrypt: work factor %d out of acceptable range [1, %d]", logN, maxWF)
	}

	label := append([]byte("age-encryption.org/v1/scrypt"), salt...)
	N := 1 << uint(logN)
	wrapKey, err := scryptDeriveKey(id.Passphrase, label, N, 8, 1, 32)
	if err != nil {
		return nil, fmt.Errorf("scrypt: key derivation failed: %w", err)
	}

	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
