	RSAPublicKey *rsa.PublicKey
	// ed25519 fields
	Ed25519Pub []byte // 32 bytes
}

// parseSSHPublicKeyBytes parses the binary SSH public key wire format.
func parseSSHPublicKeyBytes(data []byte) (*SSHPublicKey, error) {
	keyType, rest, err := sshReadString(data)
	if err != nil {
		return nil, fmt.Errorf("failed to read key type: %w", err)
	}

	key := &SSHPublicKey{
		Type:     string(keyType),
		RawBytes: data,
	}

	switch key.Type {
	case sshKeyTypeRSA:
		e, rest, err := sshReadMPInt(rest)
		if err != nil {
			return nil, fmt.Errorf("ssh-rsa: failed to read e: %w", err)
		}
		n, _, err := sshReadMPInt(rest)
		if err != nil {
			return nil, fmt.Errorf("ssh-rsa: failed to read n: %w", err)
		}
		if e.BitLen() > 30 {
			return nil, fmt.Errorf("ssh-rsa: exponent too large")
		}
		key.RSAPublicKey = &rsa.PublicKey{N: n, E: int(e.Int64())}

	case sshKeyTypeEd25519:
		ed25519Key, _, err := sshReadString(rest)
		if err != nil {
			return nil, fmt.Errorf("ssh-ed25519: failed to read key: %w", err)
		}
		if len(ed25519Key) != 32 {
			return nil, fmt.Errorf("ssh-ed25519: unexpected key length %d", len(ed25519Key))
		}
		key.Ed25519Pub = ed25519Key

	default:
		return nil, fmt.Errorf("unsupported key type %q", key.Type)
	}

	return key, nil
}

func sshReadString(data []byte) ([]byte, []byte, error) {
	if len(data) < 4 {
		return nil, nil, fmt.Errorf("short read")
	}
	n := int(binary.BigEndian.Uint32(data[:4]))
	if len(data) < 4+n {
		return nil, nil, fmt.Errorf("string too long")
	}
	return data[4 : 4+n], data[4+n:], nil
}

func sshReadMPInt(data []byte) (*big.Int, []byte, error) {
	s, rest, err := sshReadString(data)
	if err != nil {
		return nil, nil, err
	}
	return new(big.Int).SetBytes(s), rest, nil
}

// sshKeyTag computes the 4-byte tag for an SSH public key.
func sshKeyTag(rawBytes []byte) []byte {
	h := sha256.Sum256(rawBytes)
	return h[:4]
}

// SSHRSARecipient encrypts to an SSH RSA public key.
type SSHRSARecipient struct {
	PubKey *SSHPublicKey
}

func (r *SSHRSARecipient) WrapKey(fileKey []byte) (*Stanza, error) {
	if r.PubKey.RSAPublicKey.N.BitLen() < 2048 {
		return nil, fmt.Errorf("ssh-rsa: key must be at least 2048 bits")
	}
	wrappedKey, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.PubKey.RSAPublicKey, fileKey, nil)
	if err != nil {
		return nil, fmt.Errorf("ssh-rsa: encryption failed: %w", err)
	}
	tag := sshKeyTag(r.PubKey.RawBytes)
	return &Stanza{
		Type: sshKeyTypeRSA,
		Args: []string{b64std.EncodeToString(tag)},
		Body: wrappedKey,
	}, nil
}

// SSHRSAIdentity decrypts using an SSH RSA private key.
type SSHRSAIdentity struct {
	PrivKey *rsa.PrivateKey
	PubKey  *SSHPublicKey
}

func (id *SSHRSAIdentity) UnwrapKey(s *Stanza) ([]byte, error) {
	if s.Type != sshKeyTypeRSA {
		return nil, errNotMyStanza
	}
	if len(s.Args) != 1 {
		return nil, fmt.Errorf("ssh-rsa: expected 1 arg")
	}
	// Check tag
	tag, err := b64std.DecodeString(s.Args[0])
	if err != nil || len(tag) != 4 {
		return nil, fmt.Errorf("ssh-rsa: invalid tag")
	}
	ourTag := sshKeyTag(id.PubKey.RawBytes)
	if !bytes.Equal(ourTag, tag) {
		return nil, errNotMyStanza
	}
	fileKey, err := rsa.DecryptOAEP(sha256.New(), rand.Reader, id.PrivKey, s.Body, nil)
	if err != nil {
		return nil, fmt.Errorf("ssh-rsa: decryption failed: %w", err)
	}
	if len(fileKey) != ageFileKeySize {
		return nil, fmt.Errorf("ssh-rsa: unexpected file key length")
	}
	return fileKey, nil
}

// SSHEd25519Recipient encrypts to an SSH ed25519 public key.
type SSHEd25519Recipient struct {
	PubKey *SSHPublicKey
}

func (r *SSHEd25519Recipient) WrapKey(fileKey []byte) (*Stanza, error) {
	// Convert ed25519 pubkey to X25519
	x25519Pub, err := ed25519PubToX25519(r.PubKey.Ed25519Pub)
	if err != nil {
		return nil, fmt.Errorf("ssh-ed25519: key conversion failed: %w", err)
	}

	curve := ecdh.X25519()
	ephemeral, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}

	recipPub, err := curve.NewPublicKey(x25519Pub)
	if err != nil {
		return nil, fmt.Errorf("ssh-ed25519: invalid X25519 key: %w", err)
	}

	sharedSecret, err := ephemeral.ECDH(recipPub)
	if err != nil {
		return nil, fmt.Errorf("ssh-ed25519: ECDH failed: %w", err)
	}

	ephemeralPub := ephemeral.PublicKey().Bytes()
	salt := append(append([]byte{}, ephemeralPub...), x25519Pub...)

	wrapKey := make([]byte, 32)
	if _, err := io.ReadFull(hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/ssh-ed25519")), wrapKey); err != nil {
		return nil, err
	}

	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize())
	wrappedKey := aead.Seal(nil, nonce, fileKey, nil)

	tag := sshKeyTag(r.PubKey.RawBytes)
	return &Stanza{
		Type: sshKeyTypeEd25519,
		Args: []string{b64std.EncodeToString(tag), b64std.EncodeToString(ephemeralPub)},
		Body: wrappedKey,
	}, nil
}

// SSHEd25519Identity decrypts using an SSH ed25519 private key.
type SSHEd25519Identity struct {
	Seed   []byte // 32-byte seed
	PubKey *SSHPublicKey
}

func (id *SSHEd25519Identity) UnwrapKey(s *Stanza) ([]byte, error) {
	if s.Type != sshKeyTypeEd25519 {
		return nil, errNotMyStanza
	}
	if len(s.Args) != 2 {
		return nil, fmt.Errorf("ssh-ed25519: expected 2 args")
	}

	// Check tag
	tag, err := b64std.DecodeString(s.Args[0])
	if err != nil || len(tag) != 4 {
		return nil, fmt.Errorf("ssh-ed25519: invalid tag")
	}
	ourTag := sshKeyTag(id.PubKey.RawBytes)
	if !bytes.Equal(ourTag, tag) {
		return nil, errNotMyStanza
	}

	ephemeralPub, err := b64std.DecodeString(s.Args[1])
	if err != nil || len(ephemeralPub) != 32 {
		return nil, fmt.Errorf("ssh-ed25519: invalid ephemeral pubkey")
	}

	// Convert ed25519 seed to X25519 private key
	x25519Priv := ed25519SeedToX25519(id.Seed)

	curve := ecdh.X25519()
	privKey, err := curve.NewPrivateKey(x25519Priv)
	if err != nil {
		return nil, fmt.Errorf("ssh-ed25519: invalid X25519 key: %w", err)
	}

	ourX25519Pub := privKey.PublicKey().Bytes()

	ephKey, err := curve.NewPublicKey(ephemeralPub)
	if err != nil {
		return nil, fmt.Errorf("ssh-ed25519: invalid ephemeral pubkey: %w", err)
	}

	sharedSecret, err := privKey.ECDH(ephKey)
	if err != nil {
		return nil, fmt.Errorf("ssh-ed25519: ECDH failed: %w", err)
	}

	salt := append(append([]byte{}, ephemeralPub...), ourX25519Pub...)
	wrapKey := make([]byte, 32)
	if _, err := io.ReadFull(hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/ssh-ed25519")), wrapKey); err != nil {
		return nil, err
	}

	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize())
	fileKey, err := aead.Open(nil, nonce, s.Body, nil)
	if err != nil {
		return nil, fmt.Errorf("ssh-ed25519: decryption failed")
	}
	if len(fileKey) != ageFileKeySize {
		return nil, fmt.Errorf("ssh-ed25519: unexpected file key length")
	}
	return fileKey, nil
}

// ed25519PubToX25519 converts an Ed25519 public key to X25519.
// Uses the birational map: u = (1 + y) / (1 - y) mod p
func ed25519PubToX25519(ed25519Pub []byte) ([]byte, error) {
	if len(ed25519Pub) != 32 {
		return nil, fmt.Errorf("invalid ed25519 pubkey length")
	}
	// The ed25519 pubkey is compressed: y (31 bytes) + sign(x) (1 bit)
	yBytes := make([]byte, 32)
	copy(yBytes, ed25519Pub)
	yBytes[31] &= 0x7f // clear sign bit

	// Work in GF(2^255-19)
	p := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 255), big.NewInt(19))
	// y is little-endian
	y := new(big.Int).SetBytes(reverseBytesCopy(yBytes))
	one := big.NewInt(1)
	num := new(big.Int).Add(one, y)
	den := new(big.Int).Sub(p, new(big.Int).Sub(y, one)) // p - (y-1) = p - y + 1
	// den = 1 - y, but we need to handle negative mod p
	// 1 - y = -(y - 1) mod p
	den2 := new(big.Int).Sub(one, y)
	den2.Mod(den2, p)
	_ = den

	// Modular inverse
	denInv := new(big.Int).ModInverse(den2, p)
	if denInv == nil {
		return nil, fmt.Errorf("ed25519PubToX25519: degenerate point")
	}

	u := new(big.Int).Mul(num, denInv)
	u.Mod(u, p)

	uBytes := u.Bytes()
	result := make([]byte, 32)
	// Convert big-endian to little-endian
	for i, b := range uBytes {
		result[len(uBytes)-1-i] = b
	}
	return result, nil
}

// ed25519SeedToX25519 converts an ed25519 seed to an X25519 private key.
// The X25519 key is SHA-512(seed)[0:32] with clamping.
func ed25519SeedToX25519(seed []byte) []byte {
	h := sha512.Sum512(seed)
	key := h[:32]
	result := make([]byte, 32)
	copy(result, key)
	result[0] &= 248
	result[31] &= 127
	result[31] |= 64
	return result
}

func reverseBytesCopy(b []byte) []byte {
	result := make([]byte, len(b))
	for i, v := range b {
		result[len(b)-1-i] = v
	}
	return result
}

// OpenSSH private key parsing

type opensshPrivateKey struct {
	keyType string
	// For RSA
	rsaPrivKey *rsa.PrivateKey
	// For ed25519
	ed25519Seed []byte
	// Public key
	pubKey *SSHPublicKey
}

func parseOpenSSHPrivateKey(data []byte) (*opensshPrivateKey, error) {
	const magic = "openssh-key-v1\x00"
	if !bytes.HasPrefix(data, []byte(magic)) {
		return nil, fmt.Errorf("not an OpenSSH private key")
	}
	data = data[len(magic):]

	cipherName, data, err := sshReadBytes(data)
	if err != nil {
		return nil, fmt.Errorf("openssh: failed to read cipher: %w", err)
	}
	kdfName, data, err := sshReadBytes(data)
	if err != nil {
		return nil, fmt.Errorf("openssh: failed to read kdf: %w", err)
	}
	_, data, err = sshReadBytes(data) // kdf options
	if err != nil {
		return nil, fmt.Errorf("openssh: failed to read kdf options: %w", err)
	}

	if string(cipherName) != "none" || string(kdfName) != "none" {
		return nil, fmt.Errorf("openssh: encrypted private keys are not supported (passphrase-protected key)")
	}

	if len(data) < 4 {
		return nil, fmt.Errorf("openssh: truncated")
	}
	numKeys := int(binary.BigEndian.Uint32(data[:4]))
	data = data[4:]

	if numKeys != 1 {
		return nil, fmt.Errorf("openssh: expected 1 key, got %d", numKeys)
	}

	// Read public key
	pubKeyBytes, data, err := sshReadBytes(data)
	if err != nil {
		return nil, fmt.Errorf("openssh: failed to read pubkey: %w", err)
	}
	pubKey, err := parseSSHPublicKeyBytes(pubKeyBytes)
	if err != nil {
		return nil, fmt.Errorf("openssh: failed to parse pubkey: %w", err)
	}

	// Read private key blob
	privBlob, _, err := sshReadBytes(data)
	if err != nil {
		return nil, fmt.Errorf("openssh: failed to read private blob: %w", err)
	}

	// Parse private blob
	if len(privBlob) < 8 {
		return nil, fmt.Errorf("openssh: private blob too short")
	}
	check1 := binary.BigEndian.Uint32(privBlob[:4])
	check2 := binary.BigEndian.Uint32(privBlob[4:8])
	if check1 != check2 {
		return nil, fmt.Errorf("openssh: private key decryption failed (wrong passphrase?)")
	}
	privBlob = privBlob[8:]

	keyType, privBlob, err := sshReadBytes(privBlob)
	if err != nil {
		return nil, fmt.Errorf("openssh: failed to read key type: %w", err)
	}

	result := &opensshPrivateKey{
		keyType: string(keyType),
		pubKey:  pubKey,
	}

	switch result.keyType {
	case sshKeyTypeEd25519:
		// pubkey (32 bytes)
		_, privBlob, err = sshReadBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh ed25519: failed to read pubkey: %w", err)
		}
		// privkey = seed (32 bytes) || pubkey (32 bytes)
		privFull, _, err := sshReadBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh ed25519: failed to read privkey: %w", err)
		}
		if len(privFull) != 64 {
			return nil, fmt.Errorf("openssh ed25519: unexpected privkey length %d", len(privFull))
		}
		result.ed25519Seed = privFull[:32]

	case sshKeyTypeRSA:
		n, privBlob, err := sshReadMPIntBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh rsa: failed to read n: %w", err)
		}
		e, privBlob, err := sshReadMPIntBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh rsa: failed to read e: %w", err)
		}
		d, privBlob, err := sshReadMPIntBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh rsa: failed to read d: %w", err)
		}
		iqmp, privBlob, err := sshReadMPIntBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh rsa: failed to read iqmp: %w", err)
		}
		p, privBlob, err := sshReadMPIntBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh rsa: failed to read p: %w", err)
		}
		q, _, err := sshReadMPIntBytes(privBlob)
		if err != nil {
			return nil, fmt.Errorf("openssh rsa: failed to read q: %w", err)
		}
		_ = iqmp
		eInt := int(e.Int64())
		rsaKey := &rsa.PrivateKey{
			PublicKey: rsa.PublicKey{N: n, E: eInt},
			D:         d,
			Primes:    []*big.Int{p, q},
		}
		rsaKey.Precompute()
		result.rsaPrivKey = rsaKey

	default:
		return nil, fmt.Errorf("openssh: unsupported key type %q", result.keyType)
	}

	return result, nil
}

func sshReadBytes(data []byte) ([]byte, []byte, error) {
	if len(data) < 4 {
		return nil, nil, fmt.Errorf("short read")
	}
	n := int(binary.BigEndian.Uint32(data[:4]))
	if len(data) < 4+n {
		return nil, nil, fmt.Errorf("data truncated")
	}
	return data[4 : 4+n], data[4+n:], nil
}

func sshReadMPIntBytes(data []byte) (*big.Int, []byte, error) {
	s, rest, err := sshReadBytes(data)
	if err != nil {
		return nil, nil, err
	}
	return new(big.Int).SetBytes(s), rest, nil
}

// parseRSAPKCS1PrivateKey parses a PKCS#1 RSA private key (BEGIN RSA PRIVATE KEY).
func parseRSAPKCS1PrivateKey(derData []byte) (*opensshPrivateKey, error) {
	key, err := parseRSAPrivateKeyDER(derData, false)
	if err != nil {
		return nil, err
	}
	return key, nil
}

// parseRSAPKCS8PrivateKey parses a PKCS#8 RSA private key (BEGIN PRIVATE KEY).
func parseRSAPKCS8PrivateKey(derData []byte) (*opensshPrivateKey, error) {
	key, err := parseRSAPrivateKeyDER(derData, true)
	if err != nil {
		return nil, err
	}
	return key, nil
}

// parseRSAPrivateKeyDER parses RSA DER key (PKCS#1 or PKCS#8 wrapper).
func parseRSAPrivateKeyDER(derData []byte, isPKCS8 bool) (*opensshPrivateKey, error) {
	// Use Go's crypto/rsa package
	var rsaKey *rsa.PrivateKey
	var err error

	if isPKCS8 {
		// PKCS#8 format: need to parse AlgorithmIdentifier + RSA private key
		// For now, attempt to parse the inner PKCS#1
		inner, err2 := pkcs8ExtractRSAKey(derData)
		if err2 != nil {
			return nil, fmt.Errorf("PKCS#8: %w", err2)
		}
		rsaKey, err = parseRSAPKCS1DER(inner)
	} else {
		rsaKey, err = parseRSAPKCS1DER(derData)
	}
	if err != nil {
		return nil, err
	}

	// Build the SSH public key bytes for tag calculation
	pubKeyBytes, err := buildSSHRSAPubKeyBytes(rsaKey)
	if err != nil {
		return nil, err
	}
	pubKey := &SSHPublicKey{
		Type:         sshKeyTypeRSA,
		RawBytes:     pubKeyBytes,
		RSAPublicKey: &rsaKey.PublicKey,
	}

	return &opensshPrivateKey{
		keyType:    sshKeyTypeRSA,
		rsaPrivKey: rsaKey,
		pubKey:     pubKey,
	}, nil
}

// parseRSAPKCS1DER parses a PKCS#1 RSA private key from DER.
// PKCS#1: SEQUENCE { INTEGER (version), INTEGER (n), INTEGER (e), INTEGER (d), ... }
func parseRSAPKCS1DER(data []byte) (*rsa.PrivateKey, error) {
	// Simple DER parser for RSA PKCS#1
	seq, err := derReadSequence(data)
	if err != nil {
		return nil, fmt.Errorf("PKCS#1: invalid sequence: %w", err)
	}

	// version
	_, seq, err = derReadInteger(seq)
	if err != nil {
		return nil, fmt.Errorf("PKCS#1: failed to read version: %w", err)
	}
	n, seq, err := derReadInteger(seq)
	if err != nil {
		return nil, fmt.Errorf("PKCS#1: failed to read n: %w", err)
	}
	e, seq, err := derReadInteger(seq)
	if err != nil {
		return nil, fmt.Errorf("PKCS#1: failed to read e: %w", err)
	}
	d, seq, err := derReadInteger(seq)
	if err != nil {
		return nil, fmt.Errorf("PKCS#1: failed to read d: %w", err)
	}
	p, seq, err := derReadInteger(seq)
	if err != nil {
		return nil, fmt.Errorf("PKCS#1: failed to read p: %w", err)
	}
	q, _, err := derReadInteger(seq)
	if err != nil {
		return nil, fmt.Errorf("PKCS#1: failed to read q: %w", err)
	}

	rsaKey := &rsa.PrivateKey{
		PublicKey: rsa.PublicKey{N: n, E: int(e.Int64())},
		D:         d,
		Primes:    []*big.Int{p, q},
	}
	rsaKey.Precompute()
	if err := rsaKey.Validate(); err != nil {
		return nil, fmt.Errorf("PKCS#1: invalid key: %w", err)
	}
	return rsaKey, nil
}

// pkcs8ExtractRSAKey extracts the inner PKCS#1 RSA key from a PKCS#8 wrapper.
func pkcs8ExtractRSAKey(data []byte) ([]byte, error) {
	// PKCS#8: SEQUENCE { INTEGER (version), SEQUENCE { OID (algorithm), ... }, OCTET STRING (private key) }
	seq, err := derReadSequence(data)
	if err != nil {
		return nil, fmt.Errorf("invalid sequence")
	}
	// version
	_, seq, err = derReadInteger(seq)
	if err != nil {
		return nil, fmt.Errorf("failed to read version")
	}
	// AlgorithmIdentifier
	_, seq, err = derReadTag(seq, 0x30) // SEQUENCE
	if err != nil {
		return nil, fmt.Errorf("failed to read algorithm identifier")
	}
	// Private key OCTET STRING
	privKeyOctet, _, err := derReadTag(seq, 0x04) // OCTET STRING
	if err != nil {
		return nil, fmt.Errorf("failed to read private key")
	}
	return privKeyOctet, nil
}

// Simple DER parsing helpers
func derReadSequence(data []byte) ([]byte, error) {
	inner, _, err := derReadTag(data, 0x30)
	return inner, err
}

func derReadTag(data []byte, expectedTag byte) (inner, rest []byte, err error) {
	if len(data) < 2 {
		return nil, nil, fmt.Errorf("truncated DER")
	}
	if data[0] != expectedTag {
		return nil, nil, fmt.Errorf("expected tag %#x, got %#x", expectedTag, data[0])
	}
	length, headerLen, err := derReadLength(data[1:])
	if err != nil {
		return nil, nil, err
	}
	headerLen++ // include tag byte
	if len(data) < headerLen+length {
		return nil, nil, fmt.Errorf("truncated DER content")
	}
	return data[headerLen : headerLen+length], data[headerLen+length:], nil
}

func derReadLength(data []byte) (length, headerLen int, err error) {
	if len(data) == 0 {
		return 0, 0, fmt.Errorf("empty DER length")
	}
	if data[0] < 0x80 {
		return int(data[0]), 1, nil
	}
	numBytes := int(data[0] & 0x7f)
	if numBytes == 0 {
		return 0, 0, fmt.Errorf("indefinite length not supported")
	}
	if len(data) < 1+numBytes {
		return 0, 0, fmt.Errorf("truncated length")
	}
	length = 0
	for _, b := range data[1 : 1+numBytes] {
		length = (length << 8) | int(b)
	}
	return length, 1 + numBytes, nil
}

func derReadInteger(data []byte) (*big.Int, []byte, error) {
	inner, rest, err := derReadTag(data, 0x02)
	if err != nil {
		return nil, nil, err
	}
	return new(big.Int).SetBytes(inner), rest, nil
}

// buildSSHRSAPubKeyBytes builds the SSH wire format for an RSA public key.
func buildSSHRSAPubKeyBytes(key *rsa.PrivateKey) ([]byte, error) {
	var buf bytes.Buffer
	writeSSHString(&buf, []byte(sshKeyTypeRSA))
	writeSSHMPInt(&buf, big.NewInt(int64(key.PublicKey.E)))
	writeSSHMPInt(&buf, key.PublicKey.N)
	return buf.Bytes(), nil
}

func writeSSHString(w *bytes.Buffer, s []byte) {
	b := make([]byte, 4)
	binary.BigEndian.PutUint32(b, uint32(len(s)))
	w.Write(b)
	w.Write(s)
}

func writeSSHMPInt(w *bytes.Buffer, n *big.Int) {
	b := n.Bytes()
	// Prepend 0 byte if high bit is set (to indicate positive)
	if len(b) > 0 && b[0]&0x80 != 0 {
		b = append([]byte{0}, b...)
	}
	writeSSHString(w, b)
}

// Ensure crypto.Decrypter is used
var _ crypto.Decrypter = (*rsa.PrivateKey)(nil)
GOEOF

