func parseArgs(argv []string) (*cliArgs, error) {
	a := &cliArgs{}

	// We need to handle Go-style flags but with GNU-style double-dash
	// The flag package supports both -flag and --flag

	fs := flag.NewFlagSet(argv[0], flag.ContinueOnError)
