	fs.BoolVar(&armor, "armor", false, "")
	fs.BoolVar(&passphrase, "p", false, "")
	fs.BoolVar(&passphrase, "passphrase", false, "")
	fs.StringVar(&output, "o", "", "")
	fs.StringVar(&output, "output", "", "")

	// We need to handle repeatable flags manually
	// Use the flag package for parsing but track repeatable args ourselves

	// Pre-process args to extract flags before the first positional arg
	// The flag package stops at the first non-flag argument
	// But age allows flags after the input file... wait, does it?

	// From the error messages, it seems like flags must come before the input file
	// But actually age uses a custom parsing approach that detects "input file after flags"

	// Let me use a manual parser
	return parseArgManual(argv)
