	quoted := make([]string, len(extra))
	for i, s := range extra {
		quoted[i] = fmt.Sprintf("%q", s)
	}
	return fmt.Errorf("too many INPUT arguments: %s\nhint: only a single input file may be specified at a time",
		strings.Join(quoted, " "))
}

func dispatch(a *cliArgs) error {
	if a == nil {
		return nil
	}

	// Handle plugins first
	if len(a.pluginNames) > 0 {
		return handlePlugins(a)
	}

	// Validate flag combinations
	if a.decrypt && a.encrypt {
		return fmt.Errorf("-e/--encrypt can't be used with -d/--decrypt")
	}
	if a.decrypt && a.passphrase {
		return fmt.Errorf("-p/--passphrase can't be used with -d/--decrypt\nhint: note that password protected files are detected automatically")
	}
	if a.decrypt && len(a.recipients) > 0 {
		return fmt.Errorf("-r/--recipient can't be used with -d/--decrypt\nhint: did you mean to use -i/--identity to specify a private key?")
	}
	if a.decrypt && len(a.recipFiles) > 0 {
		return fmt.Errorf("-R/--recipients-file can't be used with -d/--decrypt\nhint: did you mean to use -i/--identity to specify a private key?")
	}
	if a.decrypt && a.armor {
		return fmt.Errorf("-a/--armor can't be used with -d/--decrypt\nhint: note that armored files are detected automatically, try again without -a/--armor")
	}

	if a.decrypt {
		return doDecrypt(a)
	}

	// Encrypt mode
	if !a.encryptExplicit && len(a.identities) > 0 {
		return fmt.Errorf("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt\nhint: did you forget to specify -d/--decrypt?")
	}

	if a.passphrase && len(a.recipients) > 0 {
		return fmt.Errorf("-p/--passphrase can't be combined with -r/--recipient")
	}
	if a.passphrase && len(a.recipFiles) > 0 {
		return fmt.Errorf("-p/--passphrase can't be combined with -R/--recipients-file")
	}

	hasRecipients := len(a.recipients) > 0 || len(a.recipFiles) > 0 || a.passphrase
	hasIdentitiesForEncrypt := len(a.identities) > 0 && a.encryptExplicit

	if !hasRecipients && !hasIdentitiesForEncrypt {
		fmt.Fprintf(os.Stderr, "age: error: missing recipients\n")
		fmt.Fprintf(os.Stderr, "age: hint: did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?\n")
		fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
		printUsage(os.Stderr)
		os.Exit(1)
	}

	return doEncrypt(a)
}

func doEncrypt(a *cliArgs) error {
	var recipients []Recipient

	// Parse -r recipients
	for _, r := range a.recipients {
		recip, err := parseRecipient(r)
		if err != nil {
			return err
		}
		recipients = append(recipients, recip)
	}

	// Parse -R recipient files
	for _, path := range a.recipFiles {
		var r io.Reader
		if path == "-" {
			if a.input == "" || a.input == "-" {
				return fmt.Errorf("recipients file is '-' (stdin) but no input file specified")
			}
			r = os.Stdin
		} else {
			f, err := os.Open(path)
			if err != nil {
				return fmt.Errorf("failed to parse recipient file %q: failed to open recipient file: %w", path, err)
			}
			defer f.Close()
			r = f
		}
		recips, err := parseRecipientsFile(r, path)
		if err != nil {
			return fmt.Errorf("failed to parse recipient file %q: %w", path, err)
		}
		recipients = append(recipients, recips...)
	}

	// Parse -i identity files (for symmetric encryption with -e)
	if a.encryptExplicit {
		for _, path := range a.identities {
			recips, err := identityFileToRecipients(path)
			if err != nil {
				return err
			}
			recipients = append(recipients, recips...)
		}
	}

	// Handle passphrase
	if a.passphrase {
		passphrase, err := promptPassphrase(true)
		if err != nil {
			return err
		}
		recipients = append(recipients, &ScryptRecipient{Passphrase: passphrase})
	}

	// Open input
	var input io.Reader
	if a.input == "" || a.input == "-" {
		input = os.Stdin
	} else {
		f, err := os.Open(a.input)
		if err != nil {
			return fmt.Errorf("failed to open input file %q: %w", a.input, err)
		}
		defer f.Close()
		input = f
	}

	// Open output
	var output io.WriteCloser
	var outputPath string
	if a.output == "" || a.output == "-" {
		outputPath = "-"
		if a.output == "" && !a.armor && isTerminal(os.Stdout.Fd()) {
			return fmt.Errorf("refusing to output binary to a terminal\nhint: use -o to specify an output file, or pipe to another program, or use --armor for text output")
		}
		output = os.Stdout
	} else {
		outputPath = a.output
		f, err := os.OpenFile(a.output, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
		if err != nil {
			return fmt.Errorf("failed to write header: %w", err)
		}
		defer f.Close()
		output = f
	}
	_ = outputPath

	var dst io.Writer = output
	var aw *armorWriter
	if a.armor {
		aw = newArmorWriter(output)
		dst = aw
	}

	if err := EncryptAge(dst, input, recipients); err != nil {
		return err
	}

	if aw != nil {
		if err := aw.Close(); err != nil {
			return err
		}
	}

	return nil
}

func doDecrypt(a *cliArgs) error {
	// Open input
	var inputData []byte
	var err error
	if a.input == "" || a.input == "-" {
		inputData, err = io.ReadAll(os.Stdin)
	} else {
		inputData, err = os.ReadFile(a.input)
		if err != nil {
			return fmt.Errorf("failed to open input file %q: %w", a.input, err)
		}
	}
	if err != nil {
		return fmt.Errorf("failed to read input: %w", err)
	}

	// Detect and strip armor
	var decryptData []byte
	if isArmored(inputData) {
		decryptData, err = decodeArmor(inputData)
		if err != nil {
			return fmt.Errorf("failed to read header: %w", err)
		}
	} else {
		decryptData = inputData
	}

	// Load identities
	var identities []Identity

	for _, path := range a.identities {
		ids, err := loadIdentityFile(path, a.input)
		if err != nil {
			return err
		}
		identities = append(identities, ids...)
	}

	// Check if it's a scrypt (passphrase) file
	scryptFile := isScryptFile(decryptData)

	if scryptFile && len(identities) > 0 {
		return fmt.Errorf("passphrase-encrypted files cannot be decrypted with -i/--identity\nhint: remove -i/--identity flags to decrypt a passphrase-encrypted file")
	}

	if scryptFile {
		passphrase, err := promptPassphrase(false)
		if err != nil {
			return err
		}
		identities = []Identity{&ScryptIdentity{Passphrase: passphrase, MaxWorkFactor: 30}}
	}

	if !scryptFile && len(identities) == 0 {
		return fmt.Errorf("the file is not passphrase-encrypted, identities are required\nhint: specify identities with -i/--identity or -j to decrypt this file")
	}

	// Open output
	var output io.WriteCloser
	if a.output == "" || a.output == "-" {
		output = os.Stdout
	} else {
		f, err := os.OpenFile(a.output, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
		if err != nil {
			return fmt.Errorf("failed to open output file %q: %w", a.output, err)
		}
		defer f.Close()
		output = f
	}

	if err := DecryptAge(output, bytes.NewReader(decryptData), identities); err != nil {
		return fmt.Errorf("failed to read header: %w", err)
	}

	return nil
}

func isScryptFile(data []byte) bool {
	r := bufio.NewReader(bytes.NewReader(data))
	// Skip version line
	line, err := r.ReadString('\n')
	if err != nil || strings.TrimSuffix(line, "\n") != ageFormatHeader {
		return false
	}
	for {
		line, err := r.ReadString('\n')
		if err != nil {
			return false
		}
		if strings.HasPrefix(line, "--- ") {
			return false
		}
		if strings.HasPrefix(line, "-> scrypt ") {
			return true
		}
	}
}

func loadIdentityFile(path, inputPath string) ([]Identity, error) {
	var data []byte
	var err error

	if path == "-" {
		if inputPath == "" || inputPath == "-" {
			return nil, fmt.Errorf("reading %q: failed to open file: identity is stdin but input is also stdin", path)
		}
		data, err = io.ReadAll(os.Stdin)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to read: %w", path, err)
		}
	} else {
		data, err = os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to open file: %w", path, err)
		}
	}

	// Check if it's an age-encrypted identity file
	if isArmored(data) || startsWithAgeHeader(data) {
		// Passphrase-encrypted identity file
		return loadPassphraseProtectedIdentityFile(data, path)
	}

	// Try to parse as SSH key
	if isSSHPrivateKey(data) {
		return loadSSHIdentityFile(data, path)
	}

	// Parse as age identity file (lines of AGE-SECRET-KEY-1...)
	return parseAgeIdentityFile(data, path)
}

func startsWithAgeHeader(data []byte) bool {
	return bytes.HasPrefix(bytes.TrimSpace(data), []byte(ageFormatHeader))
}

func isSSHPrivateKey(data []byte) bool {
	trimmed := bytes.TrimSpace(data)
	return bytes.HasPrefix(trimmed, []byte("-----BEGIN ")) &&
		(bytes.Contains(trimmed, []byte("PRIVATE KEY")) ||
			bytes.Contains(trimmed, []byte("RSA PRIVATE KEY")) ||
			bytes.Contains(trimmed, []byte("OPENSSH PRIVATE KEY")))
}

func loadSSHIdentityFile(data []byte, path string) ([]Identity, error) {
	var privKey *opensshPrivateKey
	var err error

	// Try to decode PEM
	block, _ := pem.Decode(data)
	if block == nil {
		return nil, fmt.Errorf("reading %q: failed to read %q: failed to decode PEM block", path, path)
	}

	switch block.Type {
	case "OPENSSH PRIVATE KEY":
		privKey, err = parseOpenSSHPrivateKey(block.Bytes)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to read %q: %w", path, path, err)
		}
	case "RSA PRIVATE KEY":
		privKey, err = parseRSAPKCS1PrivateKey(block.Bytes)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to read %q: %w", path, path, err)
		}
	case "PRIVATE KEY":
		privKey, err = parseRSAPKCS8PrivateKey(block.Bytes)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to read %q: %w", path, path, err)
		}
	default:
		return nil, fmt.Errorf("reading %q: failed to read %q: unsupported PEM block type %q", path, path, block.Type)
	}

	switch privKey.keyType {
	case sshKeyTypeEd25519:
		return []Identity{&SSHEd25519Identity{
			Seed:   privKey.ed25519Seed,
			PubKey: privKey.pubKey,
		}}, nil
	case sshKeyTypeRSA:
		return []Identity{&SSHRSAIdentity{
			PrivKey: privKey.rsaPrivKey,
			PubKey:  privKey.pubKey,
		}}, nil
	default:
		return nil, fmt.Errorf("reading %q: unsupported SSH key type %q", path, privKey.keyType)
	}
}

func loadPassphraseProtectedIdentityFile(data []byte, path string) ([]Identity, error) {
	// Decrypt the age file to get the identity file contents
	passphrase, err := promptPassphraseForIdentity(path)
	if err != nil {
		return nil, err
	}

	var plaintext bytes.Buffer
	identities := []Identity{&ScryptIdentity{Passphrase: passphrase, MaxWorkFactor: 30}}
	if err := DecryptAge(&plaintext, bytes.NewReader(data), identities); err != nil {
		return nil, fmt.Errorf("reading %q: failed to decrypt identity file: %w", path, err)
	}

	return parseAgeIdentityFile(plaintext.Bytes(), path)
}

func parseAgeIdentityFile(data []byte, path string) ([]Identity, error) {
	var identities []Identity
	scanner := bufio.NewScanner(bytes.NewReader(data))
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		id, err := parseIdentityLine(trimmed)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to read %q: error at line %d: %w", path, path, lineNum, err)
		}
		if id != nil {
			identities = append(identities, id)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("reading %q: failed to read %q: %w", path, path, err)
	}
	return identities, nil
}

func parseIdentityLine(line string) (Identity, error) {
	upperLine := strings.ToUpper(line)
	if upperLine == line && strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
		// X25519 age secret key
		hrp, privBytes, err := bech32Decode(line)
		if err != nil {
			return nil, fmt.Errorf("malformed secret key: %w", err)
		}
		if hrp != "age-secret-key-" {
			return nil, fmt.Errorf("malformed secret key: unexpected HRP %q", hrp)
		}
		if len(privBytes) != 32 {
			return nil, fmt.Errorf("malformed secret key: unexpected key length %d", len(privBytes))
		}
		id, err := NewX25519Identity(privBytes)
		if err != nil {
			return nil, fmt.Errorf("malformed secret key: %w", err)
		}
		return id, nil
	}

	// Check if it looks like a recipient (public key)
	if strings.HasPrefix(line, "age1") {
		return nil, fmt.Errorf("apparent recipient found in identities file")
	}

	return nil, fmt.Errorf("unknown identity type")
}

func identityFileToRecipients(path string) ([]Recipient, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to open identity file %q: %w", path, err)
	}

	var recipients []Recipient
	scanner := bufio.NewScanner(bytes.NewReader(data))
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		// Expect AGE-SECRET-KEY-1...
		if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
			hrp, privBytes, err := bech32Decode(line)
			if err != nil {
				return nil, fmt.Errorf("failed to read identity file %q: error at line %d: malformed secret key: %w", path, lineNum, err)
			}
			if hrp != "age-secret-key-" {
				continue
			}
			curve := ecdh.X25519()
			privKey, err := curve.NewPrivateKey(privBytes)
			if err != nil {
				return nil, fmt.Errorf("failed to read identity file %q: error at line %d: %w", path, lineNum, err)
			}
			recipients = append(recipients, &X25519Recipient{PublicKey: privKey.PublicKey().Bytes()})
		}
	}
	return recipients, nil
}

func parseRecipient(s string) (Recipient, error) {
	s = strings.TrimSpace(s)

	if strings.HasPrefix(s, "age1") {
		hrp, pubBytes, err := bech32Decode(s)
		if err != nil {
			return nil, fmt.Errorf("malformed age recipient %q: %w", s, err)
		}
		if hrp != "age" {
			return nil, fmt.Errorf("unknown recipient type: %q", s)
		}
		if len(pubBytes) != 32 {
			return nil, fmt.Errorf("malformed age recipient %q: unexpected key length %d", s, len(pubBytes))
		}
		return &X25519Recipient{PublicKey: pubBytes}, nil
	}

	if strings.HasPrefix(s, "ssh-rsa ") || strings.HasPrefix(s, "ssh-ed25519 ") {
		return parseSSHPublicKeyRecipient(s)
	}

	// Check for other SSH key types
	if isOtherSSHKeyType(s) {
		keyType := strings.SplitN(s, " ", 2)[0]
		return nil, fmt.Errorf("malformed SSH recipient: %q: unsupported SSH key type %q", s, keyType)
	}

	return nil, fmt.Errorf("unknown recipient type: %q", s)
}

func isOtherSSHKeyType(s string) bool {
	parts := strings.SplitN(s, " ", 2)
	if len(parts) < 2 {
		return false
	}
	keyType := parts[0]
	return strings.HasPrefix(keyType, "ssh-") ||
		strings.HasPrefix(keyType, "ecdsa-") ||
		strings.HasPrefix(keyType, "sk-") ||
		keyType == "ed448" ||
		keyType == "dss"
}

func parseSSHPublicKeyRecipient(s string) (Recipient, error) {
	parts := strings.Fields(s)
	if len(parts) < 2 {
		return nil, fmt.Errorf("malformed SSH recipient: %q: ssh: no key found; last parsing error for ignored line: too few fields", s)
	}

	keyType := parts[0]
	keyDataB64 := parts[1]

	keyBytes, err := base64.StdEncoding.DecodeString(keyDataB64)
	if err != nil {
		return nil, fmt.Errorf("malformed SSH recipient: %q: ssh: no key found; last parsing error for ignored line: %w", s, err)
	}

	pubKey, err := parseSSHPublicKeyBytes(keyBytes)
	if err != nil {
		return nil, fmt.Errorf("malformed SSH recipient: %q: %w", s, err)
	}

	if pubKey.Type != keyType {
		return nil, fmt.Errorf("malformed SSH recipient: %q: key type mismatch", s)
	}

	switch keyType {
	case sshKeyTypeRSA:
		if pubKey.RSAPublicKey.N.BitLen() < 2048 {
			return nil, fmt.Errorf("malformed SSH recipient: %q: RSA key must be at least 2048 bits", s)
		}
		return &SSHRSARecipient{PubKey: pubKey}, nil
	case sshKeyTypeEd25519:
		return &SSHEd25519Recipient{PubKey: pubKey}, nil
	default:
		return nil, fmt.Errorf("malformed SSH recipient: %q: unsupported key type %q", s, keyType)
	}
}

func parseRecipientsFile(r io.Reader, path string) ([]Recipient, error) {
	var recipients []Recipient
	scanner := bufio.NewScanner(r)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		recip, err := parseRecipientLine(line, path, lineNum)
		if err != nil {
			return nil, err
		}
		if recip != nil {
			recipients = append(recipients, recip)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(recipients) == 0 {
		return nil, fmt.Errorf("%q: no recipients found", path)
	}
	return recipients, nil
}

func parseRecipientLine(line, path string, lineNum int) (Recipient, error) {
	// Check for SSH key types
	parts := strings.Fields(line)
	if len(parts) >= 1 {
		keyType := parts[0]

		// Supported SSH types
		if keyType == sshKeyTypeRSA || keyType == sshKeyTypeEd25519 {
			recip, err := parseSSHPublicKeyRecipient(line)
			if err != nil {
				return nil, fmt.Errorf("%q: malformed recipient at line %d", path, lineNum)
			}
			return recip, nil
		}

		// Unsupported but valid SSH key types -> warning, skip
		if isValidSSHKeyType(keyType) {
			fmt.Fprintf(os.Stderr, "age: warning: recipients file %q: ignoring unsupported SSH key of type %q at line %d\n",
				path, keyType, lineNum)
			return nil, nil
		}
	}

	// Try as age key
	if strings.HasPrefix(line, "age1") {
		recip, err := parseRecipient(line)
		if err != nil {
			return nil, fmt.Errorf("%q: malformed recipient at line %d", path, lineNum)
		}
		return recip, nil
	}

	return nil, fmt.Errorf("%q: malformed recipient at line %d", path, lineNum)
}

func isValidSSHKeyType(keyType string) bool {
	// Known SSH key type prefixes
	return strings.HasPrefix(keyType, "ssh-") ||
		strings.HasPrefix(keyType, "ecdsa-sha2-") ||
		strings.HasPrefix(keyType, "sk-ssh-") ||
		strings.HasPrefix(keyType, "sk-ecdsa-")
}

func handlePlugins(a *cliArgs) error {
	for i, name := range a.pluginNames {
		pluginBin := "age-plugin-" + name
		if a.decrypt {
			return fmt.Errorf("%s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH\nhint: you might want to install the %q plugin\nhint: visit https://age-encryption.org/awesome#plugins for a list of available plugins",
				name, name, pluginBin, name)
		}
		_ = i
		return fmt.Errorf("failed to wrap key for recipient #%d: %s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH\nhint: you might want to install the %q plugin\nhint: visit https://age-encryption.org/awesome#plugins for a list of available plugins",
			i+len(a.recipients)+len(a.recipFiles), name, name, pluginBin, name)
	}
	return nil
}

// Terminal utilities

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}

func promptPassphrase(forEncrypt bool) ([]byte, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	defer tty.Close()

	if forEncrypt {
		fmt.Fprintf(tty, "Enter passphrase (leave empty to autogenerate a secure one): ")
		pass, err := readPassphrase(tty)
		if err != nil {
			return nil, fmt.Errorf("could not read passphrase: %w", err)
		}
		fmt.Fprintln(tty)

		if len(pass) == 0 {
			// Auto-generate
			generated := generatePassphrase(10)
			fmt.Fprintf(os.Stderr, "age: using autogenerated passphrase %q\n", generated)
			return []byte(generated), nil
		}

		fmt.Fprintf(tty, "Confirm passphrase: ")
		pass2, err := readPassphrase(tty)
		if err != nil {
			return nil, fmt.Errorf("could not read passphrase confirmation: %w", err)
		}
		fmt.Fprintln(tty)

		if string(pass) != string(pass2) {
			return nil, fmt.Errorf("passphrases don't match")
		}
		return pass, nil
	}

	// For decrypt
	fmt.Fprintf(tty, "Enter passphrase: ")
	pass, err := readPassphrase(tty)
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: %w", err)
	}
	fmt.Fprintln(tty)
	return pass, nil
}

func promptPassphraseForIdentity(path string) ([]byte, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	defer tty.Close()

	fmt.Fprintf(tty, "Enter passphrase for identity file %q: ", filepath.Base(path))
	pass, err := readPassphrase(tty)
	if err != nil {
		return nil, err
	}
	fmt.Fprintln(tty)
	return pass, nil
}

func readPassphrase(tty *os.File) ([]byte, error) {
	// Disable echo
	var oldState syscall.Termios
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, tty.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(&oldState))); errno == 0 {
		newState := oldState
		newState.Lflag &^= syscall.ECHO
		syscall.Syscall(syscall.SYS_IOCTL, tty.Fd(), syscall.TCSETS, uintptr(unsafe.Pointer(&newState)))
		defer syscall.Syscall(syscall.SYS_IOCTL, tty.Fd(), syscall.TCSETS, uintptr(unsafe.Pointer(&oldState)))
	}

	var result []byte
	buf := make([]byte, 1)
	for {
		n, err := tty.Read(buf)
		if n == 1 {
			c := buf[0]
			if c == '\n' || c == '\r' {
				break
			}
			if c == 127 || c == 8 { // backspace/delete
				if len(result) > 0 {
					result = result[:len(result)-1]
				}
				continue
			}
			result = append(result, c)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	return result, nil
}

func generatePassphrase(numWords int) string {
	words := effWordList()
	n := len(words)
	selected := make([]string, numWords)
	randBytes := make([]byte, numWords*4)
	io.ReadFull(randReader, randBytes)
	for i := 0; i < numWords; i++ {
		idx := int(uint32(randBytes[i*4])<<24|uint32(randBytes[i*4+1])<<16|
			uint32(randBytes[i*4+2])<<8|uint32(randBytes[i*4+3])) & 0x7fffffff
		selected[i] = words[idx%n]
	}
	return strings.Join(selected, "-")
}

