package main

import (
    "crypto/rand"
    "crypto/rsa"
    "crypto/sha256"
    "crypto/sha1"
    "encoding/binary"
    "encoding/pem"
    "fmt"
    "io"
    "math/big"
    "os"
    "encoding/base64"
    "strings"
)

var b64std = base64.RawStdEncoding

func parseRSAPrivKey(data []byte) *rsa.PrivateKey {
    block, _ := pem.Decode(data)
    if block == nil { panic("no PEM") }

    // Parse OpenSSH private key format
    const magic = "openssh-key-v1\x00"
    raw := block.Bytes
    if string(raw[:len(magic)]) != magic {
        panic("not openssh")
    }
    pos := len(magic)

    readStr := func(data []byte, pos int) ([]byte, int) {
        n := int(binary.BigEndian.Uint32(data[pos:]))
        return data[pos+4:pos+4+n], pos+4+n
    }
    readMPInt := func(data []byte, pos int) (*big.Int, int) {
        s, p := readStr(data, pos)
        return new(big.Int).SetBytes(s), p
    }

    // Skip cipher, kdf, kdf_options
    _, pos = readStr(raw, pos)
    _, pos = readStr(raw, pos)
    _, pos = readStr(raw, pos)

    numKeys := int(binary.BigEndian.Uint32(raw[pos:]))
    pos += 4
    _ = numKeys

    // Skip public key
    _, pos = readStr(raw, pos)

    // Read private blob
    privBlob, _ := readStr(raw, pos)

    // Parse private blob
    ppos := 8 // skip check1, check2

    _, ppos = readStr(privBlob, ppos)  // key type
    n, ppos := readMPInt(privBlob, ppos)
    e, ppos := readMPInt(privBlob, ppos)
    d, ppos := readMPInt(privBlob, ppos)
    _, ppos = readMPInt(privBlob, ppos) // iqmp
    p, ppos := readMPInt(privBlob, ppos)
    q, _ := readMPInt(privBlob, ppos)

    key := &rsa.PrivateKey{
        PublicKey: rsa.PublicKey{N: n, E: int(e.Int64())},
        D: d,
        Primes: []*big.Int{p, q},
    }
    key.Precompute()
    return key
}

func main() {
    // Load RSA private key
    data, _ := os.ReadFile("/tmp/test_rsa_key")
    rsaKey := parseRSAPrivKey(data)

    fmt.Printf("RSA key loaded: n=%d bits\n", rsaKey.N.BitLen())

    // Read the original's RSA stanza
    origData, _ := os.ReadFile("/tmp/orig_rsa.age")
    lines := strings.Split(string(origData), "\n")

    var bodyLines []string
    for i := 2; i < len(lines); i++ {
        if lines[i] == "" || strings.HasPrefix(lines[i], "---") {
            break
        }
        bodyLines = append(bodyLines, lines[i])
    }
    combined := strings.Join(bodyLines, "")
    wrapped, _ := b64std.DecodeString(combined)
    fmt.Printf("Wrapped key: %d bytes\n", len(wrapped))

    // Try different OAEP configurations
    tests := []struct {
        name  string
        decrypt func() ([]byte, error)
    }{
        {"OAEP-SHA256-SHA256", func() ([]byte, error) {
            return rsa.DecryptOAEP(sha256.New(), nil, rsaKey, wrapped, nil)
        }},
        {"OAEP-SHA1-SHA1", func() ([]byte, error) {
            return rsa.DecryptOAEP(sha1.New(), nil, rsaKey, wrapped, nil)
        }},
        {"OAEP-SHA256-SHA1 (using DecryptPKCS1v15)", func() ([]byte, error) {
            return rsa.DecryptPKCS1v15(rand.Reader, rsaKey, wrapped)
        }},
    }

    for _, t := range tests {
        fileKey, err := t.decrypt()
        if err != nil {
            fmt.Printf("%s: FAILED (%v)\n", t.name, err)
        } else {
            fmt.Printf("%s: SUCCESS! fileKey=%x\n", t.name, fileKey)
        }
    }
    _ = io.ReadFull
}
