			// End of flags
			i++
			for i < len(argv) {
				if firstPositional == "" {
					firstPositional = argv[i]
					firstPositionalIdx = i
				} else {
					positionalCount++
					extraPositionals = append(extraPositionals, argv[i])
				}
				i++
			}
			break
		}'''

new_double_dash = '''		if arg == "--" {
			// End of flags
			i++
			for i < len(argv) {
				if firstPositional == "" {
					firstPositional = argv[i]
					firstPositionalIdx = i
					a.input = argv[i]
				} else {
					positionalCount++
					extraPositionals = append(extraPositionals, argv[i])
				}
				i++
			}
			break
		}'''

if old_double_dash in content:
