# When EOF is reached while reading the version line:
# - If nothing was read: err = EOF and versionLine = ""
# - We return "parsing age header: failed to read header: EOF"
# 
# The original says: "parsing age header: file is empty" (or similar)
# Let me fix this:

python3 << 'EOF'
with open('/workspace/format.go', 'r') as f:
    content = f.read()

old = '''	versionLine, err := r.ReadString('\\n')
	if err != nil {
		return nil, fmt.Errorf("parsing age header: failed to read header: %w", err)
	}'''

new = '''	versionLine, err := r.ReadString('\\n')
	if err != nil {
		if err == io.EOF && len(versionLine) == 0 {
			return nil, fmt.Errorf("parsing age header: file is empty")
		}
		return nil, fmt.Errorf("parsing age header: failed to read header: %w", err)
	}'''

if old in content:
    content = content.replace(old, new)
    print("Fixed EOF error message")
else:
    print("Pattern not found!")
    idx = content.find('ReadString')
    print("Context:", repr(content[idx-20:idx+200]))

with open('/workspace/format.go', 'w') as f:
    f.write(content)
EOF

